window.AUTH=window.AUTH||{};window.AUTH["23-1300"]={"d":"23-1300","id":"2024/23-1300","n":"Nuclear Regulatory Commission v. Texas","briefs":[{"k":"petitioner","label":"Brief of petitioner Interim Storage Partners, LLC","date":"2024-12-02","url":"https://www.supremecourt.gov/DocketPDF/23/23-1300/333073/20241202151054027_ISP%20Opening%20Brief%20of%20Petitioner%20-%20Merits%20Stage.pdf","side":"pet","n":97},{"k":"petitioner","label":"Brief of petitioners Nuclear Regulatory Commission, et al.","date":"2024-12-02","url":"https://www.supremecourt.gov/DocketPDF/23/23-1300/333108/20241202175525383_23-1300tsUnitedStates.pdf","side":"pet","n":127},{"k":"respondent","label":"Brief of respondent Fasken Land and Minerals, Ltd.","date":"2025-01-15","url":"https://www.supremecourt.gov/DocketPDF/23/23-1300/337395/20250115182913662_Fasken%20merits%20brief%20-%20NRC%20v.%20Texas%20-%20Nos.%2023-1300%20-%2023-1312.pdf","side":"res","n":121},{"k":"respondent","label":"Brief of respondents Texas, et al.","date":"2025-01-15","url":"https://www.supremecourt.gov/DocketPDF/23/23-1300/337378/20250115145419023_23-1300%20and%2023-1312-RESPONDENTS%20BRIEF.pdf","side":"res","n":95},{"k":"reply","label":"Reply of petitioners Nuclear Regulatory Commission, et al.","date":"2025-02-14","url":"https://www.supremecourt.gov/DocketPDF/23/23-1300/342856/20250214142149917_23-1300rbUnitedStates.pdf","side":"pet","n":54},{"k":"reply","label":"Reply of petitioner Interim Storage Partners, LLC","date":"2025-02-14","url":"https://www.supremecourt.gov/DocketPDF/23/23-1300/342781/20250214100744560_Reply%20Brief%20for%20Petitioner%20ISP%20LLC.pdf","side":"pet","n":69}],"opinion":"https://www.supremecourt.gov/opinions/24pdf/605us2r51_4f57.pdf","tr":true,"items":[{"t":"case","label":"Ala. Power Co. v. FCC","cite":"311 F.3d 1357","y":2002,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/311/1357/","by":{"0":"26","1":"19","2":"39","3":"11, 12","5":"4"}},{"t":"case","label":"Ala. Power Co. v. ICC","cite":"852 F.2d 1361","y":1988,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/852/1361/","by":{"0":"27"}},{"t":"case","label":"Ali v. Fed. Bureau of Prisons","cite":"552 U.S. 214","y":2008,"id":"2007/06-9130","sc":1,"sum":"The Court agreed with the 11th Circuit and, in a 5-4 majority opinion written by Justice Clarence Thomas, held that the use of the word \"any\" should be given its normal interpretation, encompassing all federal officers whether or not they were involved in enforcing customs or excise laws.","sumSrc":"Oyez","by":{"0":"18, 35","5":"15"}},{"t":"case","label":"Am. Trucking Ass’ns, Inc. v. ICC","cite":"673 F.2d 82","y":1982,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/673/82/","by":{"0":"15, 20","1":"23, 24","2":"45"}},{"t":"case","label":"Babbitt v. Sweet Home Chapter of Communities for a Great Or.","cite":"515 U.S. 687","y":1995,"id":"1994/94-859","sc":1,"sum":"The Supreme Court held that habitat modification is a legitimate application of the word \"harm.\" First, the Court found that the Court of Appeals was incorrect in assuming that the words in the definition of \"take\" only apply to actions involving direct contact with endangered animals.","sumSrc":"Oyez","by":{"0":"36"}},{"t":"case","label":"Bd. of Governors of Fed. Rsrv. Sys. v. MCorp Fin., Inc.","cite":"502 U.S. 32","y":1991,"id":"1991/90-913","sc":1,"op":3,"sum":"The District Court lacked jurisdiction to enjoin either regulatory proceeding.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21","1":"24","2":"46","3":"24","4":"4","5":"9"}},{"t":"case","label":"Beyond Nuclear, Inc. v. NRC","cite":"113 F.4th 956","y":2024,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/113/956/","op":1,"by":{"0":"17, 19, 33-34, 42","3":"45","5":"16"}},{"t":"case","label":"Bilski v. Kappos","cite":"561 U.S. 593","y":2010,"id":"2009/08-964","sc":1,"sum":"The Court held that the \"machine-or-transformation\" test adopted by the Patent and Trademark Office (PTO) was a legal means for determining patent eligibility.","sumSrc":"Oyez","by":{"0":"36","5":"15"}},{"t":"case","label":"Borden v. United States","cite":"593 U.S. 420","y":2021,"id":"2020/19-5410","sc":1,"sum":"The decision of the Sixth Circuit—holding that an offense with a mental state of recklessness may qualify as a “violent felony” under the Armed Career Criminal Act’s elements clause, 18 U. S. C. §924(e)(2)(B)(i)—is reversed, and the case is remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"18, 38"}},{"t":"case","label":"Bowles v. Russell","cite":"551 U.S. 205","y":2007,"id":"2006/06-5306","sc":1,"sum":"The Court ruled that, even though Bowles was relying on the mistaken order of the District Court, the Circuit Court was correct to dismiss his untimely appeal.","sumSrc":"Oyez","by":{"0":"19","2":"48","3":"13"}},{"t":"case","label":"Bullcreek v. NRC","cite":"359 F.3d 536","y":2004,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/359/536/","op":8,"sum":"Noting the existence of three “private away-from-reactor storage facilities” at the time of the passage of the Nuclear Waste Policy Act in 1982; 45 Fed. Reg. at 74,698.","sumSrc":"brief:0","by":{"0":"8, 12, 14, 17-18, 29, 33-34, 40-41","1":"43","2":"39","3":"43, 45, 47","5":"10, 16, 18-21"}},{"t":"case","label":"Corley v. United States","cite":"556 U.S. 303","y":2009,"id":"2008/07-10441","sc":1,"op":1,"sum":"The Court found that voluntary confessions made more than six hours after arrest before the person has been presented before judicial officers are inadmissible.","sumSrc":"Oyez","by":{"0":"18, 36"}},{"t":"case","label":"Don’t Waste Mich. v. NRC","cite":"2023 WL 395030","y":2023,"court":"D.C. Cir. Jan. 25","op":3,"by":{"0":"9, 12-13, 18, 27, 42","1":"10, 27, 30","2":"12-13, 41","5":"5, 7"}},{"t":"case","label":"Erie-Niagara Rail Steering Comm. v. Surface Trans. Bd.","cite":"167 F.3d 111","y":1999,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/167/111/","by":{"0":"16, 22","1":"23, 24"}},{"t":"case","label":"Gage v. U.S. Atomic Energy Comm’n","cite":"479 F.2d 1214","y":1973,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/479/1214/","by":{"0":"16, 20, 25","3":"10, 12","5":"3"}},{"t":"case","label":"Harrington v. Purdue Pharma, L.P.","cite":"144 S. Ct. 2071","y":2024,"id":"2023/23-124","sc":1,"sum":"The bankruptcy code does not authorize a release and injunction that, as part of a plan of reorganization under Chapter 11, effectively seek to discharge claims against a nondebtor without the consent of affected claimants.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"18, 35","3":"41"}},{"t":"case","label":"Ind. Mich. Power Co. v. United States","cite":"422 F.3d 1369","y":2005,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/422/1369/","by":{"0":"9"}},{"t":"case","label":"Kokkonen v. Guardian Life Ins. Co. of Am.","cite":"511 U.S. 375","y":1994,"id":"1993/93-263","sc":1,"sum":"A federal district court, possessing only that power authorized by Constitution and statute, lacks jurisdiction over a claim for breach of a contract, part of the consideration for which was dismissal of an earlier federal suit. No federal statute makes that connection (if it constitutionally could) the basis for federal-court jurisdiction over the contract dispute. Moreover, the doctrine of ancillary jurisdiction …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20"}},{"t":"case","label":"Leedom v. Kyne","cite":"358 U.S. 184","y":1958,"id":"1958/14","sc":1,"op":5,"sum":"A Federal District Court had jurisdiction of an original suit to set aside the Board's determination because it was made in excess of the Board's powers. Pp. 184-191. 101 U. S. App. D. C. 398, 249 F. 2d 490, affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21","1":"24","2":"45-46","3":"6, 22, 24","4":"4","5":"8-9"}},{"t":"case","label":"Loper Bright Enters. v. Raimondo","cite":"144 S. Ct. 2244","y":2024,"id":"2023/22-451","sc":1,"op":1,"sum":"The Administrative Procedure Act requires courts to exercise their independent judgment in deciding whether an agency has acted within its statutory authority, and courts may not defer to an agency interpretation of the law simply because a statute is ambiguous; Chevron U. S. A. Inc. v. Natural Resources Defense Council, Inc., 467 U. S. 837, is overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"25, 32","1":"26, 33","3":"8, 20, 23","5":"16"}},{"t":"case","label":"Marbury v. Madison","cite":"5 U.S. 137","y":1803,"id":"1789-1850/5us137","sc":1,"sum":"A case in which the Court established a precedent for judicial review in the United States, declaring that acts of Congress that conflict with the Constitution are null and void, as the Constitution is the supreme law of the land.","sumSrc":"Oyez","by":{"0":"27"}},{"t":"case","label":"Merchs. Fast Motor Lines, Inc. v. ICC","cite":"5 F.3d 911","y":1993,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/5/911/","sum":"Noting that “at least one other circuit” declined to recognize the Fifth Circuit’s doctrine.","sumSrc":"brief:0","by":{"0":"20","2":"47"}},{"t":"case","label":"Morton v. Mancari","cite":"417 U.S. 535","y":1974,"id":"1973/73-362","sc":1,"op":1,"sum":"In addition, the Court held that Section 472 did not constitute discrimination in violation of the Fifth Amendment. Again, Justice Blackmun cited the history of \"special treatment\" granted to Indians.","sumSrc":"Oyez","by":{"0":"41","5":"21"}},{"t":"case","label":"N.J. Dep’t of Env’t Prot. v. NRC","cite":"561 F.3d 132","y":2009,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/561/132/","by":{"0":"28","5":"5"}},{"t":"case","label":"Nat’l Ass’n of State Util. Consumer Advocs. v. FCC","cite":"457 F.3d 1238","y":2006,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/457/1238/","by":{"0":"15, 21","1":"23"}},{"t":"case","label":"Nat’l Parks Conservation Ass’n v. FERC","cite":"6 F.4th 1044","y":2021,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/6/1044/","by":{"0":"25","1":"30","2":"41","5":"7"}},{"t":"case","label":"NRDC v. NRC","cite":"823 F.3d 641","y":2016,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/823/641/","by":{"0":"25","3":"19"}},{"t":"case","label":"Ohio Nuclear-Free Network v. NRC","cite":"53 F.4th 236","y":2022,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/53/236/","by":{"0":"13, 16, 25","1":"28","2":"41","3":"19","5":"3-4"}},{"t":"case","label":"Pac. Gas & Elec. Co. v. State Energy Res. Conservation & Dev. Comm’n","cite":"461 U.S. 190","y":1983,"id":"1982/81-1945","sc":1,"op":4,"sum":"The Court held that the California law did not impinge upon congressional authority. The Court found that because the rationale for enacting the law was an economic one, it did not interfere with federal regulations governing nuclear safety.","sumSrc":"Oyez","by":{"0":"2, 5","1":"2, 31, 33","3":"44, 45","5":"2, 11-12, 16"}},{"t":"case","label":"Parker Drilling Mgmt. Servs., Ltd. v. Newton","cite":"587 U.S. 601","y":2019,"id":"2018/18-389","sc":1,"sum":"Under the Outer Continental Shelf Lands Act, where federal law addresses the relevant issue, state law is not adopted as surrogate federal law on the Outer Continental Shelf.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"41","1":"43"}},{"t":"case","label":"Romag Fasteners, Inc. v. Fossil, Inc.","cite":"590 U.S. 212","y":2020,"id":"2019/18-1233","sc":1,"sum":"The Court held that under Section 35 of the Lanham Act, a plaintiff does not need to show willful infringement to receive an award of an infringer’s profits for a violation of Section 43(a).","sumSrc":"Oyez","by":{"0":"18, 38"}},{"t":"case","label":"S. C. Loveland Co. v. United States","cite":"534 F.2d 958","y":1976,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/534/958/","by":{"0":"20","1":"29","5":"7"}},{"t":"case","label":"Sheldon v. Sill","cite":"49 U.S. 441","y":1850,"id":"scdb/1850-030","sc":1,"sum":"Courts created by statute can have no jurisdiction but such as the statute confers.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"20"}},{"t":"case","label":"Siegel v. Atomic Energy Comm’n","cite":"400 F.2d 778","y":1968,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/400/778/","by":{"0":"2"}},{"t":"case","label":"Simmons v. ICC","cite":"716 F.2d 40","y":1983,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/716/40/","op":7,"by":{"0":"16, 24","1":"18","2":"43","3":"18","5":"1, 3"}},{"t":"case","label":"Skull Valley Band of Goshute Indians v. Nielson","cite":"376 F.3d 1223","y":2004,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/376/1223/","by":{"0":"14, 17, 19, 33, 41","3":"43-44","5":"16"}},{"t":"case","label":"State ex rel. Balderas v. NRC","cite":"59 F.4th 1112","y":2023,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.4th/59/1112/","by":{"0":"13, 15-16, 19, 21, 25, 27, 41-42","1":"10, 11, 23, 28","2":"13","3":"19, 20","5":"3, 17"}},{"t":"case","label":"Sw. Airlines Co. v. Saxon","cite":"596 U.S. 450","y":2022,"url":"https://supreme.justia.com/cases/federal/us/596/450/","sc":1,"by":{"0":"35","3":"27, 40"}},{"t":"case","label":"Texas v. United States","cite":"891 F.3d 553","y":2018,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/891/553/","by":{"0":"10","1":"48","3":"4, 5"}},{"t":"case","label":"Wales Transp., Inc. v. ICC","cite":"728 F.2d 774","y":1984,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/728/774/","op":1,"by":{"0":"20","1":"23, 24","2":"45, 47"}},{"t":"case","label":"Water Transp. Ass’n v. ICC","cite":"819 F.2d 1189","y":1987,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/819/1189/","op":1,"ar":1,"by":{"0":"26","1":"28","2":"41","4":"7","5":"4"}},{"t":"case","label":"West Virginia v. EPA","cite":"597 U.S. 697","y":2022,"url":"https://supreme.justia.com/cases/federal/us/597/697/","sc":1,"op":8,"by":{"0":"14, 38-39","1":"48, 49","2":"25, 32-34","3":"8, 31","5":"21-22"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"law","label":"Pub. L. No. 93-584","url":"https://www.govinfo.gov/link/statute/88/1917","by":{"0":"20","1":"24"}},{"t":"usc","label":"5 U.S.C. § 702","url":"https://www.law.cornell.edu/uscode/text/5/702","stext":{"head":"§702. Right of review","paras":[[0,"A person suffering legal wrong because of agency action, or adversely affected or aggrieved by agency action within the meaning of a relevant statute, is entitled to judicial review thereof. An action in a court of the United States seeking relief other than money damages and stating a claim that an agency or an officer or employee thereof acted or failed to act in an official capacity or under color of legal authority shall not be dismissed nor relief therein be denied on the ground that it is against the United States or that the United States is an indispensable party. The United States may be named as a defendant in any such action, and a judgment or decree may be entered against the United States: Provided, That any mandatory or injunctive decree shall specify the Federal officer or officers (by name or by title), and their successors in office, personally responsible for compliance. Nothing herein (1) affects other limitations on judicial review or the power or duty of the court to dismiss any action or deny relief on any other appropriate legal or equitable ground; or (2) confers authority to grant relief if any other statute that grants consent to suit expressly or impliedly forbids the relief which is sought."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/702?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§702. Right of review","tname":"Government Organization and Employees","by":{"0":"22, 24","1":"13, 18","2":"43","4":"6","5":"3"}},{"t":"law","label":"Pub. L. No. 85-681","url":"https://www.govinfo.gov/link/statute/72/632","by":{"0":"7","1":"40"}},{"t":"law","label":"Approval of Yucca Mountain Site, Pub. L. No. 107-200","url":"https://www.govinfo.gov/link/plaw/107/public/200","by":{"0":"9"}},{"t":"usc","label":"42 U.S.C. § 2011","url":"https://www.law.cornell.edu/uscode/text/42/2011","subs":["(a)","(b)"],"stext":{"head":"§2011. Congressional declaration of policy","paras":[[0,"Atomic energy is capable of application for peaceful as well as military purposes. It is therefore declared to be the policy of the United States that—"],[1,"(a) the development, use, and control of atomic energy shall be directed so as to make the maximum contribution to the general welfare, subject at all times to the paramount objective of making the maximum contribution to the common defense and security; and"],[1,"(b) the development, use, and control of atomic energy shall be directed so as to promote world peace, improve the general welfare, increase the standard of living, and strengthen free competition in private enterprise."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2011?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2011. Congressional declaration of policy","tname":"The Public Health and Welfare","by":{"0":"1, 5, 37, 5, 17, 30-31, 5, 31, 38","1":"2, 33","2":"2-4, 12-13, 15-16, 21-29, 32-35, 37-39, 42-43, 45, 47","4":"2","5":"14, 16, 14"}},{"t":"usc","label":"42 U.S.C. § 2012","url":"https://www.law.cornell.edu/uscode/text/42/2012","subs":["(a)","(c)","(d)"],"by":{"0":"5, 6, 17, 30, 6, 17, 30","5":"14"}},{"t":"usc","label":"42 U.S.C. § 2013","url":"https://www.law.cornell.edu/uscode/text/42/2013","subs":["(d)","(a)","(b)"],"by":{"0":"5","1":"2, 2, 2, 33","2":"2, 31","5":"14"}},{"t":"usc","label":"42 U.S.C. § 2014","url":"https://www.law.cornell.edu/uscode/text/42/2014","subs":["(v)","(aa)","(cc)","(e)(3)(a)","(e)(3)(aa)","(e)","(z)","(ee)","(e)(2)","(e)(1)"],"stext":{"head":"§2014. Definitions","paras":[[0,"The intent of Congress in the definitions as given in this section should be construed from the words or phrases used in the definitions. As used in this chapter:"],[0,"(a) The term \"agency of the United States\" means the executive branch of the United States, or any Government agency, or the legislative branch of the United States, or any agency, committee, commission, office, or other establishment in the legislative branch, or the judicial branch of the United States, or any office, agency, committee, commission, or other establishment in the judicial branch."],[0,"(b) The term \"agreement for cooperation\" means any agreement with another nation or regional defense organization authorized or permitted by sections 2074, 2077, 2094, 2112, 2121(c), 2133, 2134, or 2164 of this title, and made pursuant to section 2153 of this title."],[0,"(c) The term \"atomic energy\" means all forms of energy released in the course of nuclear fission or nuclear transformation."],[0,"(d) The term \"atomic weapon\" means any device utilizing atomic energy, exclusive of the means for transporting or propelling the device (where such means is a separable and divisible part of the device), the principal purpose of which is for use as, or for development of, a weapon, a weapon prototype, or a weapon test device."],[0,"(e) The term \"byproduct material\" means—"],[1,"(1) any radioactive material (except special nuclear material) yielded in or made radioactive by exposure to the radiation incident to the process of producing or utilizing special nuclear material;"],[1,"(2) the tailings or wastes produced by the extraction or concentration of uranium or thorium from any ore processed primarily for its source material content;"],[1,"(3)(A) any discrete source of radium-226 that is produced, extracted, or converted after extraction, before, on, or after August 8, 2005, for use for a commercial, medical, or research activity; or"],[1,"(B) any material that—"],[2,"(i) has been made radioactive by use of a particle accelerator, including by use of a fusion machine; and"],[2,"(ii) if made radioactive by use of a particle accelerator that is not a fusion machine, is produced, extracted, or converted after extraction, before, on, or after August 8, 2005, for use for a commercial, medical, or research activity; and"],[1,"(4) any discrete source of naturally occurring radioactive material, other than source material, that—"],[2,"(A) the Commission, in consultation with the Administrator of the Environmental Protection Agency, the Secretary of Energy, the Secretary of Homeland Security, and the head of any other appropriate Federal agency, determines would pose a threat similar to the threat posed by a discrete source of radium-226 to the public health and safety or the common defense and security; and"],[2,"(B) before, on, or after August 8, 2005, is extracted or converted after extraction for use in a commercial, medical, or research activity."],[0,"(f) The term \"Commission\" means the Atomic Energy Commission."],[0,"(g) The term \"common defense and security\" means the common defense and security of the United States."],[0,"(h) The term \"defense information\" means any information in any category determined by any Government agency authorized to classify information, as being information respecting, relating to, or affecting the national defense."],[0,"(i) The term \"design\" means (1) specifications, plans, drawings, blueprints, and other items of like nature; (2) the information contained therein; or (3) the research and development data pertinent to the information contained therein."],[0,"(j) The term \"extraordinary nuclear occurrence\" means any event causing a discharge or dispersal of source, special nuclear, or byproduct material from its intended place of confinement in amounts offsite, or causing radiation levels offsite, which the Nuclear Regulatory Commission or the Secretary of Energy, as appropriate, determines to be substantial, and which the Nuclear Regulatory Commission or the Secretary of Energy, as appropriate, determines has resulted or will probably result in substantial damages to persons offsite or property offsite. Any determination by the Nuclear Regulatory Commission or the Secretary of Energy, as appropriate, that such an event has, or has not, occurred shall be final and conclusive, and no other official or any court shall have power or jurisdiction to review any such determination. The Nuclear Regulatory Commission or the Secretary of Energy, as appropriate, shall establish criteria in writing setting forth the basis upon which such determination shall be made. As used in this subsection, \"offsite\" means away from \"the location\" or \"the contract location\" as defined in the applicable Nuclear Regulatory Commission or the Secretary of Energy, as appropriate, indemnity agreement, entered into pursuant to section 2210 of this title."],[0,"(k) The term \"financial protection\" means the ability to respond in damages for public liability and to meet the costs of investigating and defending claims and settling suits for such damages."],[0,"(l) The term \"Government agency\" means any executive department, commission, independent establishment, corporation, wholly or partly owned by the United States of America which is an instrumentality of the United States, or any board, bureau, division, service, office, officer, authority, administration, or other establishment in the executive branch of the Government."],[0,"(m) The term \"indemnitor\" means (1) any insurer with respect to his obligations under a policy of insurance furnished as proof of financial protection; (2) any licensee, contractor or other person who is obligated under any other form of financial protection, with respect to such obligations; and (3) the Nuclear Regulatory Commission or the Secretary of Energy, as appropriate, with respect to any obligation undertaken by it in indemnity agreement entered into pursuant to section 2210 of this title."],[0,"(n) The term \"international arrangement\" means any international agreement hereafter approved by the Congress or any treaty during the time such agreement or treaty is in full force and effect, but does not include any agreement for cooperation."],[0,"(o) The term \"Energy Committees\" means the Committee on Energy and Natural Resources of the Senate and the Committee on Energy and Commerce of the House of Representatives."],[0,"(p) The term \"licensed activity\" means an activity licensed pursuant to this chapter and covered by the provisions of section 2210(a) of this title."],[0,"(q) The term \"nuclear incident\" means any occurrence, including an extraordinary nuclear occurrence, within the United States causing, within or outside the United States, bodily injury, sickness, disease, or death, or loss of or damage to property, or loss of use of property, arising out of or resulting from the radioactive, toxic, explosive, or other hazardous properties of source, special nuclear, or byproduct material: Provided, however, That as the term is used in section 2210(l) of this title, it shall include any such occurrence outside the United States: And provided further, That as the term is used in section 2210(d) of this title, it shall include any such occurrence outside the United States: And provided further, That as the term is used in section 2210(c) of this title, it shall include any such occurrence outside both the United States and any other nation if such occurrence arises out of or results from the radioactive, toxic, explosive, or other hazardous properties of source, special nuclear, or byproduct material licensed pursuant to subchapters V, VI, VII, and IX of this division, which is used in connection with the operation of a licensed stationary production or utilization facility or which moves outside the territorial limits of the United States in transit from one person licensed by the Nuclear Regulatory Commission to another person licensed by the Nuclear Regulatory Commission."],[0,"(r) The term \"operator\" means any individual who manipulates the controls of a utilization or production facility."],[0,"(s) The term \"person\" means (1) any individual, corporation, partnership, firm, association, trust, estate, public or private institution, group, Government agency other than the Commission, any State or any political subdivision of, or any political entity within a State, any foreign government or nation or any political subdivision of any such government or nation, or other entity; and (2) any legal successor, representative, agent, or agency of the foregoing."],[0,"(t) The term \"person indemnified\" means (1) with respect to a nuclear incident occurring within the United States or outside the United States as the term is used in section 2210(c) of this title, and with respect to any nuclear incident in connection with the design, development, construction, operation, repair, maintenance, or use of the nuclear ship Savannah, the person with whom an indemnity agreement is executed or who is required to maintain financial protection, and any other person who may be liable for public liability or (2) with respect to any other nuclear incident occurring outside the United States, the person with whom an indemnity agreement is executed and any other person who may be liable for public liability by reason of his activities under any contract with the Secretary of Energy or any project to which indemnification under the provisions of section 2210(d) of this title has been extended or under any subcontract, purchase order, or other agreement, of any tier, under any such contract or project."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2014?type=usc&year=mostrecent&link-type=html"},"head":"§2014. Definitions","tname":"The Public Health and Welfare","by":{"0":"36, 37, 36, 6, 6","1":"3, 37, 3, 3, 37","2":"2, 3, 26","4":"15, 12","5":"11"}},{"t":"usc","label":"42 U.S.C. § 2073","url":"https://www.law.cornell.edu/uscode/text/42/2073","subs":["(a)(1)","(a)(2)","(a)(3)","(a)(4)","(a)"],"stext":{"head":"§2073. Domestic distribution of special nuclear material","paras":[[0,"(a) Licenses"],[0,"The Commission is authorized (i) to issue licenses to transfer or receive in interstate commerce, transfer, deliver, acquire, possess, own, receive possession of or title to, import, or export under the terms of an agreement for cooperation arranged pursuant to section 2153 of this title, special nuclear material, (ii) to make special nuclear material available for the period of the license, and, (iii) to distribute special nuclear material within the United States to qualified applicants requesting such material—"],[1,"(1) for the conduct of research and development activities of the types specified in section 2051 of this title;"],[1,"(2) for use in the conduct of research and development activities or in medical therapy under a license issued pursuant to section 2134 of this title;"],[1,"(3) for use under a license issued pursuant to section 2133 of this title;"],[1,"(4) for such other uses as the Commission determines to be appropriate to carry out the purposes of this chapter."],[0,"(b) Minimum criteria for licenses"],[0,"The Commission shall establish, by rule, minimum criteria for the issuance of specific or general licenses for the distribution of special nuclear material depending upon the degree of importance to the common defense and security or to the health and safety of the public of—"],[1,"(1) the physical characteristics of the special nuclear material to be distributed;"],[1,"(2) the quantities of special nuclear material to be distributed; and"],[1,"(3) the intended use of the special nuclear material to be distributed."],[0,"(c) Manner of distribution; charges for material sold; agreements; charges for material leased"],[0,"(1) The Commission may distribute special nuclear material licensed under this section by sale, lease, lease with option to buy, or grant: Provided, however, That unless otherwise authorized by law, the Commission shall not after December 31, 1970, distribute special nuclear material except by sale to any person who possesses or operates a utilization facility under a license issued pursuant to section 2133 or 2134(b) of this title for use in the course of activities under such license; nor shall the Commission permit any such person after June 30, 1973, to continue leasing for use in the course of such activities special nuclear material previously leased to such person by the Commission."],[0,"(2) The Commission shall establish reasonable sales prices for the special nuclear material licensed and distributed by sale under this section. Such sales prices shall be established on a nondiscriminatory basis which, in the opinion of the Commission, will provide reasonable compensation to the Government for such special nuclear material."],[0,"(3) The Commission is authorized to enter into agreements with licensees for such period of time as the Commission may deem necessary or desirable to distribute to such licensees such quantities of special nuclear material as may be necessary for the conduct of the licensed activity. In such agreements, the Commission may agree to repurchase any special nuclear material licensed and distributed by sale which is not consumed in the course of the licensed activity, or any uranium remaining after irradiation of such special nuclear material, at a repurchase price not to exceed the Commission's sale price for comparable special nuclear material or uranium in effect at the time of delivery of such material to the Commission."],[0,"(4) The Commission may make a reasonable charge, determined pursuant to this section, for the use of special nuclear material licensed and distributed by lease under subsection (a)(1), (2) or (4) and shall make a reasonable charge determined pursuant to this section for the use of special nuclear material licensed and distributed by lease under subsection (a)(3). The Commission shall establish criteria in writing for the determination of whether special nuclear material will be distributed by grant and for the determination of whether a charge will be made for the use of special nuclear material licensed and distributed by lease under subsection (a)(1), (2) or (4), considering, among other things, whether the licensee is a nonprofit or eleemosynary institution and the purposes for which the special nuclear material will be used."],[0,"(d) Determination of charges"],[0,"In determining the reasonable charge to be made by the Commission for the use of special nuclear material distributed by lease to licensees of utilization or production facilities licensed pursuant to section 2133 or 2134 of this title, in addition to consideration of the cost thereof, the Commission shall take into consideration—"],[1,"(1) the use to be made of the special nuclear material;"],[1,"(2) the extent to which the use of the special nuclear material will advance the development of the peaceful uses of atomic energy;"],[1,"(3) the energy value of the special nuclear material in the particular use for which the license is issued;"],[1,"(4) whether the special nuclear material is to be used in facilities licensed pursuant to section 2133 or 2134 of this title. In this respect, the Commission shall, insofar as practicable, make uniform, nondiscriminatory charges for the use of special nuclear material distributed to facilities licensed pursuant to section 2133 of this title; and"],[1,"(5) with respect to special nuclear material consumed in a facility licensed pursuant to section 2133 of this title, the Commission shall make a further charge equivalent to the sale price for similar special nuclear material established by the Commission in accordance with subsection (c)(2), and the Commission may make such a charge with respect to such material consumed in a facility licensed pursuant to section 2134 of this title."],[0,"(e) License conditions"],[0,"Each license issued pursuant to this section shall contain and be subject to the following conditions—"],[1,"(1) Repealed. Pub. L. 88–489, §8, Aug. 26, 1964, 78 Stat. 604."],[1,"(2) no right to the special nuclear material shall be conferred by the license except as defined by the license;"],[1,"(3) neither the license nor any right under the license shall be assigned or otherwise transferred in violation of the provisions of this chapter;"],[1,"(4) all special nuclear material shall be subject to the right of recapture or control reserved by section 2138 of this title and to all other provisions of this chapter;"],[1,"(5) no special nuclear material may be used in any utilization or production facility except in accordance with the provisions of this chapter;"],[1,"(6) special nuclear material shall be distributed only on terms, as may be established by rule of the Commission, such that no user will be permitted to construct an atomic weapon;"],[1,"(7) special nuclear material shall be distributed only pursuant to such safety standards as may be established by rule of the Commission to protect health and to minimize danger to life or property; and"],[1,"(8) except to the extent that the indemnification and limitation of liability provisions of section 2210 of this title apply, the licensee will hold the United States and the Commission harmless from any damages resulting from the use or possession of special nuclear material by the licensee."],[0,"(f) Distribution for independent research and development activities"],[0,"The Commission is directed to distribute within the United States sufficient special nuclear material to permit the conduct of widespread independent research and development activities to the maximum extent practicable. In the event that applications for special nuclear material exceed the amount available for distribution, preference shall be given to those activities which are most likely, in the opinion of the Commission, to contribute to basic research, to the development of peacetime uses of atomic energy, or to the economic and military strength of the Nation."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2073?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2073. Domestic distribution of special nuclear material","tname":"The Public Health and Welfare","by":{"0":"6, 30, 34, 30, 34, 30, 35-36, 6-7, 17, 30, 36","1":"31, 31, 31, 31, 31, 31, 31","2":"28, 35, 2, 30, 30","4":"17, 14, 15","5":"14-15, 14-15, 15, 15"}},{"t":"usc","label":"42 U.S.C. § 2092","url":"https://www.law.cornell.edu/uscode/text/42/2092","by":{"0":"6","1":"36","4":"18","5":"13"}},{"t":"usc","label":"42 U.S.C. § 2093","url":"https://www.law.cornell.edu/uscode/text/42/2093","subs":["(a)(1)","(a)(2)","(a)(3)","(a)(4)","(a)"],"stext":{"head":"§2093. Domestic distribution of source material","paras":[[0,"(a) License"],[0,"The Commission is authorized to issue licenses for and to distribute source material within the United States to qualified applicants requesting such material—"],[1,"(1) for the conduct of research and development activities of the types specified in section 2051 of this title;"],[1,"(2) for use in the conduct of research and development activities or in medical therapy under a license issued pursuant to section 2134 of this title;"],[1,"(3) for use under a license issued pursuant to section 2133 of this title; or"],[1,"(4) for any other use approved by the Commission as an aid to science or industry."],[0,"(b) Minimum criteria for licenses"],[0,"The Commission shall establish, by rule, minimum criteria for the issuance of specific or general licenses for the distribution of source material depending upon the degree of importance to the common defense and security or to the health and safety of the public of—"],[1,"(1) the physical characteristics of the source material to be distributed;"],[1,"(2) the quantities of source material to be distributed; and"],[1,"(3) the intended use of the source material to be distributed."],[0,"(c) Determination of charges"],[0,"The Commission may make a reasonable charge determined pursuant to section 2201(m) of this title for the source material licensed and distributed under subsection (a)(1), (a)(2), or (a)(4) and shall make a reasonable charge determined pursuant to section 2201(m) of this title, for the source material licensed and distributed under subsection (a)(3). The Commission shall establish criteria in writing for the determination of whether a charge will be made for the source material licensed and distributed under subsection (a)(1), (a)(2), or (a)(4), considering, among other things, whether the licensee is a nonprofit or eleemosynary institution and the purposes for which the source material will be used."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2093?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2093. Domestic distribution of source material","tname":"The Public Health and Welfare","by":{"0":"6, 30, 34, 31, 34, 31, 35-36, 7, 17, 31, 36","1":"36, 36, 36, 36, 36, 36, 36","2":"28, 35, 30, 30, 32","4":"17, 14, 15","5":"14-15, 14-15, 15, 15"}},{"t":"usc","label":"42 U.S.C. § 2111","url":"https://www.law.cornell.edu/uscode/text/42/2111","subs":["(a)","(b)","(c)"],"stext":{"head":"§2111. Domestic distribution","paras":[[0,"(a) In general"],[0,"No person may transfer or receive in interstate commerce, manufacture, produce, transfer, acquire, own, possess, import, or export any byproduct material, except to the extent authorized by this section, section 2112 or section 2114 of this title. The Commission is authorized to issue general or specific licenses to applicants seeking to use byproduct material for research or development purposes, for medical therapy, industrial uses, agricultural uses, or such other useful applications as may be developed. The Commission may distribute, sell, loan, or lease such byproduct material as it owns to qualified applicants with or without charge: Provided, however, That, for byproduct material to be distributed by the Commission for a charge, the Commission shall establish prices on such equitable basis as, in the opinion of the Commission, (a) will provide reasonable compensation to the Government for such material, (b) will not discourage the use of such material or the development of sources of supply of such material independent of the Commission, and (c) will encourage research and development. In distributing such material, the Commission shall give preference to applicants proposing to use such material either in the conduct of research and development or in medical therapy. The Commission shall not permit the distribution of any byproduct material to any licensee, and shall recall or order the recall of any distributed material from any licensee, who is not equipped to observe or who fails to observe such safety standards to protect health as may be established by the Commission or who uses such material in violation of law or regulation of the Commission or in a manner other than as disclosed in the application therefor or approved by the Commission. The Commission is authorized to establish classes of byproduct material and to exempt certain classes or quantities of material or kinds of uses or users from the requirements for a license set forth in this section when it makes a finding that the exemption of such classes or quantities of such material or such kinds of uses or users will not constitute an unreasonable risk to the common defense and security and to the health and safety of the public."],[0,"(b) Requirements"],[0,"(1) In general"],[1,"Except as provided in paragraph (2), byproduct material, as defined in paragraphs (3) and (4) of section 2014(e) of this title, may only be transferred to and disposed of in a disposal facility that—"],[2,"(A) is adequate to protect public health and safety; and"],[2,"(B)(i) is licensed by the Commission; or"],[2,"(ii) is licensed by a State that has entered into an agreement with the Commission under section 2021(b) of this title, if the licensing requirements of the State are compatible with the licensing requirements of the Commission."],[0,"(2) Effect of subsection"],[1,"Nothing in this subsection affects the authority of any entity to dispose of byproduct material, as defined in paragraphs (3) and (4) of section 2014(e) of this title, at a disposal facility in accordance with any Federal or State solid or hazardous waste law, including the Solid Waste Disposal Act (42 U.S.C. 6901 et seq.)."],[0,"(c) Treatment as low-level radioactive waste"],[0,"Byproduct material, as defined in paragraphs (3) and (4) of section 2014(e) of this title, disposed of under this section shall not be considered to be low-level radioactive waste for the purposes of—"],[1,"(1) section 2 of the Low-Level Radioactive Waste Policy Act (42 U.S.C. 2021b); or"],[1,"(2) carrying out a compact that is—"],[2,"(A) entered into in accordance with that Act (42 U.S.C. 2021b et seq.); and"],[2,"(B) approved by Congress."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2111?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2111. Domestic distribution","tname":"The Public Health and Welfare","by":{"0":"6, 7, 17, 31, 37, 37","1":"36, 36, 36, 36","2":"28, 35, 30","4":"18, 14, 15, 17","5":"13, 14"}},{"t":"usc","label":"42 U.S.C. § 2133","url":"https://www.law.cornell.edu/uscode/text/42/2133","stext":{"head":"§2133. Commercial licenses","paras":[[0,"(a) Conditions"],[0,"The Commission is authorized to issue licenses to persons applying therefor to transfer or receive in interstate commerce, manufacture, produce, transfer, acquire, possess, use, import, or export under the terms of an agreement for cooperation arranged pursuant to section 2153 of this title, utilization or production facilities for industrial or commercial purposes. Such licenses shall be issued in accordance with the provisions of subchapter XV and subject to such conditions as the Commission may by rule or regulation establish to effectuate the purposes and provisions of this chapter."],[0,"(b) Nonexclusive basis"],[0,"The Commission shall issue such licenses on a nonexclusive basis to persons applying therefor (1) whose proposed activities will serve a useful purpose proportionate to the quantities of special nuclear material or source material to be utilized; (2) who are equipped to observe and who agree to observe such safety standards to protect health and to minimize danger to life or property as the Commission may by rule establish; and (3) who agree to make available to the Commission such technical information and data concerning activities under such licenses as the Commission may determine necessary to promote the common defense and security and to protect the health and safety of the public. All such information may be used by the Commission only for the purposes of the common defense and security and to protect the health and safety of the public."],[0,"(c) License period"],[0,"Each such license shall be issued for a specified period, as determined by the Commission, depending on the type of activity to be licensed, but not exceeding forty years from the authorization to commence operations, and may be renewed upon the expiration of such period."],[0,"(d) Limitations"],[0,"No license under this section may be given to any person for activities which are not under or within the jurisdiction of the United States, except for the export of production or utilization facilities under terms of an agreement for cooperation arranged pursuant to section 2153 of this title, or except under the provisions of section 2139 of this title. No license may be issued to an alien or any corporation or other entity if the Commission knows or has reason to believe it is owned, controlled, or dominated by an alien, a foreign corporation, or a foreign government. In any event, no license may be issued to any person within the United States if, in the opinion of the Commission, the issuance of a license to such person would be inimical to the common defense and security or to the health and safety of the public."],[0,"(f) 1 Accident notification condition; license revocation; license amendment to include condition"],[0,"Each license issued for a utilization facility under this section or section 2134(b) of this title shall require as a condition thereof that in case of any accident which could result in an unplanned release of quantities of fission products in excess of allowable limits for normal operation established by the Commission, the licensee shall immediately so notify the Commission. Violation of the condition prescribed by this subsection may, in the Commission's discretion, constitute grounds for license revocation. In accordance with section 2237 of this title, the Commission shall promptly amend each license for a utilization facility issued under this section or section 2134(b) of this title which is in effect on June 30, 1980, to include the provisions required under this subsection."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2133?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2133. Commercial licenses","tname":"The Public Health and Welfare","by":{"0":"36","1":"36"}},{"t":"usc","label":"42 U.S.C. § 2201","url":"https://www.law.cornell.edu/uscode/text/42/2201","subs":["(b)","(h)","(p)"],"stext":{"head":"§2201. General duties of Commission","paras":[[0,"In the performance of its functions the Commission is authorized to—"],[0,"(a) Establishment of advisory boards"],[1,"establish advisory boards to advise with and make recommendations to the Commission on legislation, policies, administration, research, and other matters, provided that the Commission issues regulations setting forth the scope, procedure, and limitations of the authority of each such board;"],[0,"(b) Standards governing use and possession of material"],[1,"establish by rule, regulation, or order, such standards and instructions to govern the possession and use of special nuclear material, source material, and byproduct material as the Commission may deem necessary or desirable to promote the common defense and security or to protect health or to minimize danger to life or property; in addition, the Commission shall prescribe such regulations or orders as may be necessary or desirable to promote the Nation's common defense and security with regard to control, ownership, or possession of any equipment or device, or important component part especially designed for such equipment or device, capable of separating the isotopes of uranium or enriching uranium in the isotope 235;"],[0,"(c) Studies and investigations"],[1,"make such studies and investigations, obtain such information, and hold such meetings or hearings as the Commission may deem necessary or proper to assist it in exercising any authority provided in this chapter, or in the administration or enforcement of this chapter, or any regulations or orders issued thereunder. For such purposes the Commission is authorized to administer oaths and affirmations, and by subpena to require any person to appear and testify, or to appear and produce documents, or both, at any designated place. Witnesses subpenaed under this subsection shall be paid the same fees and mileage as are paid witnesses in the district courts of the United States;"],[0,"(d) Employment of personnel"],[1,"appoint and fix the compensation of such officers and employees as may be necessary to carry out the functions of the Commission. Such officers and employees shall be appointed in accordance with the civil-service laws and their compensation fixed in accordance with chapter 51 and subchapter III of chapter 53 of title 5, except that, to the extent the Commission deems such action necessary to the discharge of its responsibilities, personnel may be employed and their compensation fixed without regard to such laws: Provided, however, That no officer or employee (except such officers and employees whose compensation is fixed by law, and scientific and technical personnel up to a limit of the highest rate of grade 18 of the General Schedule) whose position would be subject to chapter 51 and subchapter III of chapter 53 of title 5, if such provisions were applicable to such position, shall be paid a salary at a rate in excess of the rate payable under such provisions for positions of equivalent difficulty or responsibility. Such rates of compensation may be adopted by the Commission as may be authorized by chapter 51 and subchapter III of chapter 53 of title 5, as of the same date such rates are authorized for positions subject to such provisions. The Commission shall make adequate provision for administrative review of any determination to dismiss any employee;"],[0,"(e) Acquisition of material, property, etc.; negotiation of commercial leases"],[1,"acquire such material, property, equipment, and facilities, establish or construct such buildings and facilities, and modify such buildings and facilities from time to time, as it may deem necessary, and construct, acquire, provide, or arrange for such facilities and services (at project sites where such facilities and services are not available) for the housing, health, safety, welfare, and recreation of personnel employed by the Commission as it may deem necessary, subject to the provisions of section 2224 of this title: Provided, however, That in the communities owned by the Commission, the Commission is authorized to grant privileges, leases and permits upon adjusted terms which (at the time of the initial grant of any privilege grant, lease, or permit, or renewal thereof, or in order to avoid inequities or undue hardship prior to the sale by the United States of property affected by such grant) are fair and reasonable to responsible persons to operate commercial businesses without advertising and without advertising 1 and without securing competitive bids, but taking into consideration, in addition to the price, and among other things (1) the quality and type of services required by the residents of the community, (2) the experience of each concession applicant in the community and its surrounding area, (3) the ability of the concession applicant to meet the needs of the community, and (4) the contribution the concession applicant has made or will make to the other activities and general welfare of the community;"],[0,"(f) Utilization of other Federal agencies"],[1,"with the consent of the agency concerned, utilize or employ the services or personnel of any Government agency or any State or local government, or voluntary or uncompensated personnel, to perform such functions on its behalf as may appear desirable;"],[0,"(g) Acquisition of real and personal property"],[1,"acquire, purchase, lease, and hold real and personal property, including patents, as agent of and on behalf of the United States, subject to the provisions of section 2224 of this title, and to sell, lease, grant, and dispose of such real and personal property as provided in this chapter;"],[0,"(h) Consideration of license applications"],[1,"consider in a single application one or more of the activities for which a license is required by this chapter, combine in a single license one or more of such activities, and permit the applicant or licensee to incorporate by reference pertinent information already filed with the Commission;"],[0,"(i) Regulations governing Restricted Data"],[1,"prescribe such regulations or orders as it may deem necessary (1) to protect Restricted Data received by any person in connection with any activity authorized pursuant to this chapter, (2) to guard against the loss or diversion of any special nuclear material acquired by any person pursuant to section 2073 of this title or produced by any person in connection with any activity authorized pursuant to this chapter, to prevent any use or disposition thereof which the Commission may determine to be inimical to the common defense and security, including regulations or orders designating activities, involving quantities of special nuclear material which in the opinion of the Commission are important to the common defense and security, that may be conducted only by persons whose character, associations, and loyalty shall have been investigated under standards and specifications established by the Commission and as to whom the Commission shall have determined that permitting each such person to conduct the activity will not be inimical to the common defense and security, (3) to govern any activity authorized pursuant to this chapter, including standards and restrictions governing the design, location, and operation of facilities used in the conduct of such activity, in order to protect health and to minimize danger to life or property, and (4) to ensure that sufficient funds will be available for the decommissioning of any production or utilization facility licensed under section 2133 or 2134(b) of this title, including standards and restrictions governing the control, maintenance, use, and disbursement by any former licensee under this chapter that has control over any fund for the decommissioning of the facility;"],[0,"(j) Disposition of surplus materials"],[1,"without regard to the provisions of chapters 1 to 11 (except section 559) of title 40 and division C (except sections 3302, 3307(e), 3501(b), 3509, 3906, 4710, and 4711) of subtitle I of title 41, or any other law, make such disposition as it may deem desirable of (1) radioactive materials, and (2) any other property, the special disposition of which is, in the opinion of the Commission, in the interest of the national security: Provided, however, That the property furnished to licensees in accordance with the provisions of subsection (m) shall not be deemed to be property disposed of by the Commission pursuant to this subsection;"],[0,"(k) Carrying of firearms; authority to make arrests without warrant"],[1,"authorize such of its members, officers, and employees as it deems necessary in the interest of the common defense and security to carry firearms while in the discharge of their official duties. The Commission may also authorize such of those employees of its contractors and subcontractors (at any tier) engaged in the protection of property under the jurisdiction of the United States located at facilities owned by or contracted to the United States or being transported to or from such facilities as it deems necessary in the interests of the common defense and security to carry firearms while in the discharge of their official duties. A person authorized to carry firearms under this subsection may, while in the performance of, and in connection with, official duties, make arrests without warrant for any offense against the United States committed in that person's presence or for any felony cognizable under the laws of the United States if that person has reasonable ground to believe that the individual to be arrested has committed or is committing such felony. An employee of a contractor or subcontractor authorized to carry firearms under this subsection may make such arrests only when the individual to be arrested is within, or in direct flight from, the area of such offense. A person granted authority to make arrests by this subsection may exercise that authority only in the enforcement of (1) laws regarding the property of the United States in the custody of the Department of Energy, the Nuclear Regulatory Commission, or a contractor of the Department of Energy or Nuclear Regulatory Commission, or (2) any provision of this chapter that may subject an offender to a fine, imprisonment, or both. The arrest authority conferred by this subsection is in addition to any arrest authority under other laws. The Secretary, with the approval of the Attorney General, shall issue guidelines to implement this subsection;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2201?type=usc&year=mostrecent&link-type=html"},"head":"§2201. General duties of Commission","tname":"The Public Health and Welfare","by":{"0":"6, 17, 29, 38","1":"3, 4, 3, 37, 42, 7","2":"29","4":"13","5":"16"}},{"t":"usc","label":"42 U.S.C. § 2239","url":"https://www.law.cornell.edu/uscode/text/42/2239","subs":["(a)(1)(A)","(b)(1)","(a)(1)(B)(iv)","(a)"],"stext":{"head":"§2239. Hearings and judicial review","paras":[[0,"(a)(1)(A) In any proceeding under this chapter, for the granting, suspending, revoking, or amending of any license or construction permit, or application to transfer control, and in any proceeding for the issuance or modification of rules and regulations dealing with the activities of licensees, and in any proceeding for the payment of compensation, an award or royalties under sections 1 2183, 2187, 2236(c) or 2238 of this title, the Commission shall grant a hearing upon the request of any person whose interest may be affected by the proceeding, and shall admit any such person as a party to such proceeding. The Commission shall hold a hearing after thirty days' notice and publication once in the Federal Register, on each application under section 2133 or 2134(b) of this title for a construction permit for a facility, and on any application under section 2134(c) of this title for a construction permit for a testing facility. In cases where such a construction permit has been issued following the holding of such a hearing, the Commission may, in the absence of a request therefor by any person whose interest may be affected, issue an operating license or an amendment to a construction permit or an amendment to an operating license without a hearing, but upon thirty days' notice and publication once in the Federal Register of its intent to do so. The Commission may dispense with such thirty days' notice and publication with respect to any application for an amendment to a construction permit or an amendment to an operating license upon a determination by the Commission that the amendment involves no significant hazards consideration."],[0,"(B)(i) Not less than 180 days before the date scheduled for initial loading of fuel into a plant by a licensee that has been issued a combined construction permit and operating license under section 2235(b) of this title, the Commission shall publish in the Federal Register notice of intended operation. That notice shall provide that any person whose interest may be affected by operation of the plant, may within 60 days request the Commission to hold a hearing on whether the facility as constructed complies, or on completion will comply, with the acceptance criteria of the license."],[0,"(ii) A request for hearing under clause (i) shall show, prima facie, that one or more of the acceptance criteria in the combined license have not been, or will not be met, and the specific operational consequences of nonconformance that would be contrary to providing reasonable assurance of adequate protection of the public health and safety."],[0,"(iii) After receiving a request for a hearing under clause (i), the Commission expeditiously shall either deny or grant the request. If the request is granted, the Commission shall determine, after considering petitioners' prima facie showing and any answers thereto, whether during a period of interim operation, there will be reasonable assurance of adequate protection of the public health and safety. If the Commission determines that there is such reasonable assurance, it shall allow operation during an interim period under the combined license."],[0,"(iv) The Commission, in its discretion, shall determine appropriate hearing procedures, whether informal or formal adjudicatory, for any hearing under clause (i), and shall state its reasons therefor."],[0,"(v) The Commission shall, to the maximum possible extent, render a decision on issues raised by the hearing request within 180 days of the publication of the notice provided by clause (i) or the anticipated date for initial loading of fuel into the reactor, whichever is later. Commencement of operation under a combined license is not subject to subparagraph (A)."],[0,"(2)(A) The Commission may issue and make immediately effective any amendment to an operating license or any amendment to a combined construction and operating license, upon a determination by the Commission that such amendment involves no significant hazards consideration, notwithstanding the pendency before the Commission of a request for a hearing from any person. Such amendment may be issued and made immediately effective in advance of the holding and completion of any required hearing. In determining under this section whether such amendment involves no significant hazards consideration, the Commission shall consult with the State in which the facility involved is located. In all other respects such amendment shall meet the requirements of this chapter."],[0,"(B) The Commission shall periodically (but not less frequently than once every thirty days) publish notice of any amendments issued, or proposed to be issued, as provided in subparagraph (A). Each such notice shall include all amendments issued, or proposed to be issued, since the date of publication of the last such periodic notice. Such notice shall, with respect to each amendment or proposed amendment (i) identify the facility involved; and (ii) provide a brief description of such amendment. Nothing in this subsection shall be construed to delay the effective date of any amendment."],[0,"(C) The Commission shall, during the ninety-day period following the effective date of this paragraph, promulgate regulations establishing (i) standards for determining whether any amendment to an operating license or any amendment to a combined construction and operating license involves no significant hazards consideration; (ii) criteria for providing or, in emergency situations, dispensing with prior notice and reasonable opportunity for public comment on any such determination, which criteria shall take into account the exigency of the need for the amendment involved; and (iii) procedures for consultation on any such determination with the State in which the facility involved is located."],[0,"(b) The following Commission actions shall be subject to judicial review in the manner prescribed in chapter 158 of title 28 and chapter 7 of title 5:"],[1,"(1) Any final order entered in any proceeding of the kind specified in subsection (a)."],[1,"(2) Any final order allowing or prohibiting a facility to begin operating under a combined construction and operating license."],[1,"(3) Any final order establishing by regulation standards to govern the Department of Energy's gaseous diffusion uranium enrichment plants, including any such facilities leased to a corporation established under the USEC Privatization Act [42 U.S.C. 2297h et seq.]."],[1,"(4) Any final determination under section 2297f(c) of this title relating to whether the gaseous diffusion plants, including any such facilities leased to a corporation established under the USEC Privatization Act [42 U.S.C. 2297h et seq.], are in compliance with the Commission's standards governing the gaseous diffusion plants and all applicable laws."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2239?type=usc&year=mostrecent&link-type=html"},"op":31,"head":"§2239. Hearings and judicial review","tname":"The Public Health and Welfare","by":{"0":"10, 24, 10, 24","1":"27, 27, 27, 43","2":"7, 7, 8, 10, 16, 37, 8","4":"9"}},{"t":"law","label":"Pub. L. No. 93-438","url":"https://www.govinfo.gov/link/statute/88/1233","by":{"0":"7"}},{"t":"usc","label":"28 U.S.C. § 2342","url":"https://www.law.cornell.edu/uscode/text/28/2342","subs":["(1)","(4)"],"by":{"0":"1, 19, 10, 24","1":"8, 16, 8, 19","2":"7, 45, 7, 7"}},{"t":"usc","label":"28 U.S.C. § 2344","url":"https://www.law.cornell.edu/uscode/text/28/2344","stext":{"head":"§2344. Review of orders; time; notice; contents of petition; service","paras":[[0,"On the entry of a final order reviewable under this chapter, the agency shall promptly give notice thereof by service or publication in accordance with its rules. Any party aggrieved by the final order may, within 60 days after its entry, file a petition to review the order in the court of appeals wherein venue lies. The action shall be against the United States. The petition shall contain a concise statement of—"],[1,"(1) the nature of the proceedings as to which review is sought;"],[1,"(2) the facts on which venue is based;"],[1,"(3) the grounds on which relief is sought; and"],[1,"(4) the relief prayed."],[0,"The petitioner shall attach to the petition, as exhibits, copies of the order, report, or decision of the agency. The clerk shall serve a true copy of the petition on the agency and on the Attorney General by registered mail, with request for a return receipt."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2344?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§2344. Review of orders; time; notice; contents of petition; service","tname":"Judiciary and Judicial Procedure","by":{"0":"1, 10, 16, 19-20, 24","1":"27","2":"7, 16, 37, 45","4":"1, 2, 4, 8, 10, 11","5":"1, 3-4"}},{"t":"usc","label":"28 U.S.C. § 2348","url":"https://www.law.cornell.edu/uscode/text/28/2348","by":{"0":"25","1":"27","2":"39","4":"10","5":"4"}},{"t":"usc","label":"42 U.S.C. § 4321","url":"https://www.law.cornell.edu/uscode/text/42/4321","stext":{"head":"§4321. Congressional declaration of purpose","paras":[[0,"The purposes of this chapter are: To declare a national policy which will encourage productive and enjoyable harmony between man and his environment; to promote efforts which will prevent or eliminate damage to the environment and biosphere and stimulate the health and welfare of man; to enrich the understanding of the ecological systems and natural resources important to the Nation; and to establish a Council on Environmental Quality."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/4321?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§4321. Congressional declaration of purpose","tname":"The Public Health and Welfare","by":{"0":"11","1":"27"}},{"t":"usc","label":"42 U.S.C. § 10101","url":"https://www.law.cornell.edu/uscode/text/42/10101","subs":["(9)","(23)"],"stext":{"head":"§10101. Definitions","paras":[[0,"For purposes of this chapter:"],[1,"(1) The term \"Administrator\" means the Administrator of the Environmental Protection Agency."],[1,"(2) The term \"affected Indian tribe\" means any Indian tribe—"],[2,"(A) within whose reservation boundaries a monitored retrievable storage facility, test and evaluation facility, or a repository for high-level radioactive waste or spent fuel is proposed to be located;"],[2,"(B) whose federally defined possessory or usage rights to other lands outside of the reservation's boundaries arising out of congressionally ratified treaties may be substantially and adversely affected by the locating of such a facility: Provided, That the Secretary of the Interior finds, upon the petition of the appropriate governmental officials of the tribe, that such effects are both substantial and adverse to the tribe; 1"],[1,"(3) The term \"atomic energy defense activity\" means any activity of the Secretary performed in whole or in part in carrying out any of the following functions:"],[2,"(A) naval reactors development;"],[2,"(B) weapons activities including defense inertial confinement fusion;"],[2,"(C) verification and control technology;"],[2,"(D) defense nuclear materials production;"],[2,"(E) defense nuclear waste and materials by-products management;"],[2,"(F) defense nuclear materials security and safeguards and security investigations; and"],[2,"(G) defense research and development."],[1,"(4) The term \"candidate site\" means an area, within a geologic and hydrologic system, that is recommended by the Secretary under section 10132 of this title for site characterization, approved by the President under section 10132 of this title for site characterization, or undergoing site characterization under section 10133 of this title."],[1,"(5) The term \"civilian nuclear activity\" means any atomic energy activity other than an atomic energy defense activity."],[1,"(6) The term \"civilian nuclear power reactor\" means a civilian nuclear powerplant required to be licensed under section 2133 or 2134(b) of this title."],[1,"(7) The term \"Commission\" means the Nuclear Regulatory Commission."],[1,"(8) The term \"Department\" means the Department of Energy."],[1,"(9) The term \"disposal\" means the emplacement in a repository of high-level radioactive waste, spent nuclear fuel, or other highly radioactive material with no foreseeable intent of recovery, whether or not such emplacement permits the recovery of such waste."],[1,"(10) The terms \"disposal package\" and \"package\" mean the primary container that holds, and is in contact with, solidified high-level radioactive waste, spent nuclear fuel, or other radioactive materials, and any overpacks that are emplaced at a repository."],[1,"(11) The term \"engineered barriers\" means manmade components of a disposal system designed to prevent the release of radionuclides into the geologic medium involved. Such term includes the high-level radioactive waste form, high-level radioactive waste canisters, and other materials placed over and around such canisters."],[1,"(12) The term \"high-level radioactive waste\" means—"],[2,"(A) the highly radioactive material resulting from the reprocessing of spent nuclear fuel, including liquid waste produced directly in reprocessing and any solid material derived from such liquid waste that contains fission products in sufficient concentrations; and"],[2,"(B) other highly radioactive material that the Commission, consistent with existing law, determines by rule requires permanent isolation."],[1,"(13) The term \"Federal agency\" means any Executive agency, as defined in section 105 of title 5."],[1,"(14) The term \"Governor\" means the chief executive officer of a State."],[1,"(15) The term \"Indian tribe\" means any Indian tribe, band, nation, or other organized group or community of Indians recognized as eligible for the services provided to Indians by the Secretary of the Interior because of their status as Indians, including any Alaska Native village, as defined in section 3(c) of the Alaska Native Claims Settlement Act (43 U.S.C. 1602(c))."],[1,"(16) The term \"low-level radioactive waste\" means radioactive material that—"],[2,"(A) is not high-level radioactive waste, spent nuclear fuel, transuranic waste, or by-product material as defined in section 2014(e)(2) of this title; and"],[2,"(B) the Commission, consistent with existing law, classifies as low-level radioactive waste."],[1,"(17) The term \"Office\" means the Office of Civilian Radioactive Waste Management established in section 10224 2 of this title."],[1,"(18) The term \"repository\" means any system licensed by the Commission that is intended to be used for, or may be used for, the permanent deep geologic disposal of high-level radioactive waste and spent nuclear fuel, whether or not such system is designed to permit the recovery, for a limited period during initial operation, of any materials placed in such system. Such term includes both surface and subsurface areas at which high-level radioactive waste and spent nuclear fuel handling activities are conducted."],[1,"(19) The term \"reservation\" means—"],[2,"(A) any Indian reservation or dependent Indian community referred to in clause (a) or (b) of section 1151 of title 18; or"],[2,"(B) any land selected by an Alaska Native village or regional corporation under the provisions of the Alaska Native Claims Settlement Act (43 U.S.C. 1601 et seq.)."],[1,"(20) The term \"Secretary\" means the Secretary of Energy."],[1,"(21) The term \"site characterization\" means—"],[2,"(A) siting research activities with respect to a test and evaluation facility at a candidate site; and"],[2,"(B) activities, whether in the laboratory or in the field, undertaken to establish the geologic condition and the ranges of the parameters of a candidate site relevant to the location of a repository, including borings, surface excavations, excavations of exploratory shafts, limited subsurface lateral excavations and borings, and in situ testing needed to evaluate the suitability of a candidate site for the location of a repository, but not including preliminary borings and geophysical testing needed to assess whether site characterization should be undertaken."],[1,"(22) The term \"siting research\" means activities, including borings, surface excavations, shaft excavations, subsurface lateral excavations and borings, and in situ testing, to determine the suitability of a site for a test and evaluation facility."],[1,"(23) The term \"spent nuclear fuel\" means fuel that has been withdrawn from a nuclear reactor following irradiation, the constituent elements of which have not been separated by reprocessing."],[1,"(24) The term \"State\" means each of the several States, the District of Columbia, the Commonwealth of Puerto Rico, the Virgin Islands, Guam, American Samoa, the Northern Mariana Islands, the Trust Territory of the Pacific Islands, and any other territory or possession of the United States."],[1,"(25) The term \"storage\" means retention of high-level radioactive waste, spent nuclear fuel, or transuranic waste with the intent to recover such waste or fuel for subsequent use, processing, or disposal."],[1,"(26) The term \"Storage Fund\" means the Interim Storage Fund established in section 10156(c) 2 of this title."],[1,"(27) The term \"test and evaluation facility\" means an at-depth, prototypic, underground cavity with subsurface lateral excavations extending from a central shaft that is used for research and development purposes, including the development of data and experience for the safe handling and disposal of solidified high-level radioactive waste, transuranic waste, or spent nuclear fuel."],[1,"(28) The term \"unit of general local government\" means any borough, city, county, parish, town, township, village, or other general purpose political subdivision of a State."],[1,"(29) The term \"Waste Fund\" means the Nuclear Waste Fund established in section 10222(c) of this title."],[1,"(30) The term \"Yucca Mountain site\" means the candidate site in the State of Nevada recommended by the Secretary to the President under section 10132(b)(1)(B) of this title on May 27, 1986."],[1,"(31) The term \"affected unit of local government\" means the unit of local government with jurisdiction over the site of a repository or a monitored retrievable storage facility. Such term may, at the discretion of the Secretary, include units of local government that are contiguous with such unit."],[1,"(32) The term \"Negotiator\" means the Nuclear Waste Negotiator."],[1,"(33) As used in subchapter IV, the term \"Office\" means the Office of the Nuclear Waste Negotiator established under subchapter IV of this chapter."],[1,"(34) The term \"monitored retrievable storage facility\" means the storage facility described in section 10161(b)(1) of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/10101?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§10101. Definitions","tname":"The Public Health and Welfare","by":{"0":"1-2, 9","1":"5, 42, 5","2":"1, 3, 5-6, 12-15, 17-27, 29, 31-32, 34, 37, 45, 47, 26","4":"2, 12"}},{"t":"usc","label":"42 U.S.C. § 10141","url":"https://www.law.cornell.edu/uscode/text/42/10141","subs":["(b)","(b)(1)(A)(i)"],"by":{"0":"9","4":"20"}},{"t":"usc","label":"42 U.S.C. § 10151","url":"https://www.law.cornell.edu/uscode/text/42/10151","subs":["(a)(1)","(a)(2)","(a)(3)","(b)(1)","(b)(2)"],"by":{"0":"39","1":"5, 44, 46, 5, 44, 46, 43, 43, 43, 43, 43","2":"31, 17, 6, 17, 24, 6, 17, 17-18, 20-21, 6, 18, 21","4":"18, 17, 20, 21","5":"18"}},{"t":"usc","label":"42 U.S.C. § 10155","url":"https://www.law.cornell.edu/uscode/text/42/10155","subs":["(a)(1)(A)(i)","(h)","(a)(1)","(a)(1)(A)","(a)(1)(B)","(a)(1)(C)","(b)(1)(A)","(b)(1)(B)","(b)(1)(B)(i)","(d)"],"stext":{"head":"§10155. Storage of spent nuclear fuel","paras":[[0,"(a) Storage capacity"],[0,"(1) Subject to section 10107 of this title, the Secretary shall provide, in accordance with paragraph (5), not more than 1,900 metric tons of capacity for the storage of spent nuclear fuel from civilian nuclear power reactors. Such storage capacity shall be provided through any one or more of the following methods, used in any combination determined by the Secretary to be appropriate:"],[1,"(A) use of available capacity at one or more facilities owned by the Federal Government on January 7, 1983, including the modification and expansion of any such facilities, if the Commission determines that such use will adequately protect the public health and safety, except that such use shall not—"],[2,"(i) render such facilities subject to licensing under the Atomic Energy Act of 1954 (42 U.S.C. 2011 et seq.) or the Energy Reorganization Act of 1974 (42 U.S.C. 5801 et seq.); or"],[2,"(ii) except as provided in subsection (c) require the preparation of an environmental impact statement under section 102(2)(C) of the National Environmental Policy Act of 1969 (42 U.S.C. 4332(2)(C)), such 1 facility is already being used, or has previously been used, for such storage or for any similar purpose.2"],[1,"(B) acquisition of any modular or mobile spent nuclear fuel storage equipment, including spent nuclear fuel storage casks, and provision of such equipment, to any person generating or holding title to spent nuclear fuel, at the site of any civilian nuclear power reactor operated by such person or at any site owned by the Federal Government on January 7, 1983;"],[1,"(C) construction of storage capacity at any site of a civilian nuclear power reactor."],[0,"(2) Storage capacity authorized by paragraph (1) shall not be provided at any Federal or non-Federal site within which there is a candidate site for a repository. The restriction in the preceding sentence shall only apply until such time as the Secretary decides that such candidate site is no longer a candidate site under consideration for development as a repository."],[0,"(3) In selecting methods of providing storage capacity under paragraph (1), the Secretary shall consider the timeliness of the availability of each such method and shall seek to minimize the transportation of spent nuclear fuel, the public health and safety impacts, and the costs of providing such storage capacity."],[0,"(4) In providing storage capacity through any method described in paragraph (1), the Secretary shall comply with any applicable requirements for licensing or authorization of such method, except as provided in paragraph (1)(A)(i)."],[0,"(5) The Secretary shall ensure that storage capacity is made available under paragraph (1) when needed, as determined on the basis of the storage needs specified in contracts entered into under section 10156(a) of this title, and shall accept upon request any spent nuclear fuel as covered under such contracts."],[0,"(6) For purposes of paragraph (1)(A), the term \"facility\" means any building or structure."],[0,"(b) Contracts"],[0,"(1) Subject to the capacity limitation established in subsections (a)(1) and (d), the Secretary shall offer to enter into, and may enter into, contracts under section 10156(a) of this title with any person generating or owning spent nuclear fuel for purposes of providing storage capacity for such spent fuel under this section only if the Commission determines that—"],[1,"(A) adequate storage capacity to ensure the continued orderly operation of the civilian nuclear power reactor at which such spent nuclear fuel is generated cannot reasonably be provided by the person owning and operating such reactor at such site, or at the site of any other civilian nuclear power reactor operated by such person, and such capacity cannot be made available in a timely manner through any method described in subparagraph (B); and"],[1,"(B) such person is diligently pursuing licensed alternatives to the use of Federal storage capacity for the storage of spent nuclear fuel expected to be generated by such person in the future, including—"],[2,"(i) expansion of storage facilities at the site of any civilian nuclear power reactor operated by such person;"],[2,"(ii) construction of new or additional storage facilities at the site of any civilian nuclear power reactor operated by such person;"],[2,"(iii) acquisition of modular or mobile spent nuclear fuel storage equipment, including spent nuclear fuel storage casks, for use at the site of any civilian nuclear power reactor operated by such person; and"],[2,"(iv) transshipment to another civilian nuclear power reactor owned by such person."],[0,"(2) In making the determination described in paragraph (1)(A), the Commission shall ensure maintenance of a full core reserve storage capability at the site of the civilian nuclear power reactor involved unless the Commission determines that maintenance of such capability is not necessary for the continued orderly operation of such reactor."],[0,"(3) The Commission shall complete the determinations required in paragraph (1) with respect to any request for storage capacity not later than 6 months after receipt of such request by the Commission."],[0,"(c) Environmental review"],[0,"(1) The provision of 300 or more metric tons of storage capacity at any one Federal site under subsection (a)(1)(A) shall be considered to be a major Federal action requiring preparation of an environmental impact statement under section 102(2)(C) of the National Environmental Policy Act of 1969 (42 U.S.C. 4332(2)(C))."],[0,"(2)(A) The Secretary shall prepare, and make available to the public, an environmental assessment of the probable impacts of any provision of less than 300 metric tons of storage capacity at any one Federal site under subsection (a)(1)(A) that requires the modification or expansion of any facility at the site, and a discussion of alternative activities that may be undertaken to avoid such impacts. Such environmental assessment shall include—"],[1,"(i) an estimate of the amount of storage capacity to be made available at such site;"],[1,"(ii) an evaluation as to whether the facilities to be used at such site are suitable for the provision of such storage capacity;"],[1,"(iii) a description of activities planned by the Secretary with respect to the modification or expansion of the facilities to be used at such site;"],[1,"(iv) an evaluation of the effects of the provision of such storage capacity at such site on the public health and safety, and the environment;"],[1,"(v) a reasonable comparative evaluation of current information with respect to such site and facilities and other sites and facilities available for the provision of such storage capacity;"],[1,"(vi) a description of any other sites and facilities that have been considered by the Secretary for the provision of such storage capacity; and"],[1,"(vii) an assessment of the regional and local impacts of providing such storage capacity at such site, including the impacts on transportation."],[0,"(B) The issuance of any environmental assessment under this paragraph shall be considered to be a final agency action subject to judicial review in accordance with the provisions of chapter 7 of title 5. Such judicial review shall be limited to the sufficiency of such assessment with respect to the items described in clauses (i) through (vii) of subparagraph (A)."],[0,"(3) Judicial review of any environmental impact statement or environmental assessment prepared pursuant to this subsection shall be conducted in accordance with the provisions of section 10139 of this title."],[0,"(d) Review of sites and State participation"],[0,"(1) In carrying out the provisions of this part with regard to any interim storage of spent fuel from civilian nuclear power reactors which the Secretary is authorized by this section to provide, the Secretary shall, as soon as practicable, notify, in writing, the Governor and the State legislature of any State and the Tribal Council of any affected Indian tribe in such State in which is located a potentially acceptable site or facility for such interim storage of spent fuel of his intention to investigate that site or facility."],[0,"(2) During the course of investigation of such site or facility, the Secretary shall keep the Governor, State legislature, and affected Tribal Council currently informed of the progress of the work, and results of the investigation. At the time of selection by the Secretary of any site or existing facility, but prior to undertaking any site-specific work or alterations, the Secretary shall promptly notify the Governor, the legislature, and any affected Tribal Council in writing of such selection, and subject to the provisions of paragraph (6) of this subsection, shall promptly enter into negotiations with such State and affected Tribal Council to establish a cooperative agreement under which such State and Council shall have the right to participate in a process of consultation and cooperation, based on public health and safety and environmental concerns, in all stages of the planning, development, modification, expansion, operation, and closure of storage capacity at a site or facility within such State for the interim storage of spent fuel from civilian nuclear power reactors. Public participation in the negotiation of such an agreement shall be provided for and encouraged by the Secretary, the State, and the affected Tribal Council. The Secretary, in cooperation with the States and Indian tribes, shall develop and publish minimum guidelines for public participation in such negotiations, but the adequacy of such guidelines or any failure to comply with such guidelines shall not be a basis for judicial review."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/10155?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§10155. Storage of spent nuclear fuel","tname":"The Public Health and Welfare","by":{"0":"9, 40","1":"43","2":"19, 18, 21, 19, 6, 19, 19, 6, 19, 19, 6, 6, 20, 23, 32, 39","4":"19, 19, 22, 19","5":"17, 20"}},{"t":"usc","label":"42 U.S.C. § 10161","url":"https://www.law.cornell.edu/uscode/text/42/10161","subs":["(d)"],"by":{"0":"40","1":"43"}},{"t":"reg","label":"10 C.F.R. § 2.309","url":"https://www.ecfr.gov/current/title-10/section-2.309","subs":["(a)","(h)"],"by":{"0":"24","5":"5"}},{"t":"reg","label":"General Electric Co.; Renewal of Materials License for the Storage of Spent Fuel, 47 Fed. Reg. 20,231","url":"https://www.govinfo.gov/link/fr/47/20231","by":{"0":"8"}},{"t":"reg","label":"Licensing Requirements for the Storage of Spent Fuel in an Independent Fuel Spent Storage Installation, 45 Fed. Reg. 74,693","url":"https://www.govinfo.gov/link/fr/45/74693","by":{"0":"8, 32","1":"4","2":"3-4, 27, 33, 35","3":"3, 37","4":"16","5":"11"}},{"t":"reg","label":"Private Fuel Storage, Limited Liability Company; Notice of Issuance of Materials License SNM2513 for the Private Fuel Storage Facility, 71 Fed. Reg. 10,068","url":"https://www.govinfo.gov/link/fr/71/10068","by":{"0":"8","1":"5"}},{"t":"reg","label":"Public Service Co. of Colorado; Issuance of Materials License SNM-2504, Ft. St. Vrain Independent Spent Fuel Storage; Installation at the Ft, 56 Fed. Reg. 57,539","url":"https://www.govinfo.gov/link/fr/56/57539","by":{"0":"8","1":"6"}},{"t":"reg","label":"Storage of Spent Nuclear Fuel in an Independent Spent Fuel Storage Installation (ISFSI): Proposed Rule, 43 Fed. Reg. 46,309","url":"https://www.govinfo.gov/link/fr/43/46309","by":{"0":"8","2":"3-4, 32-33","3":"3"}},{"t":"case","label":"Axon Enterprise, Inc. v. FTC","cite":"598 U.S. 175","y":2023,"id":"2022/21-86","sc":1,"sum":"The statutory review schemes set out in the Securities Exchange Act and Federal Trade Commission Act do not displace a district court’s federal-question jurisdiction over claims challenging as unconstitutional the structure or existence of the SEC or FTC.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"25","4":"3, 4"}},{"t":"case","label":"City of Arlington v. FCC","cite":"569 U.S. 290","y":2013,"id":"2012/11-1545","sc":1,"sum":"The Court found that the courts must apply the Chevron doctrine and defer to an agency's interpretation of its jurisdiction when that jurisdiction is called into question.","sumSrc":"Oyez","by":{"1":"23"}},{"t":"case","label":"Dairyland Power Coop. v. United States","cite":"645 F.3d 1363","y":2011,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/645/1363/","by":{"1":"7"}},{"t":"case","label":"Dubin v. United States","cite":"599 U.S. 110","y":2023,"id":"2022/22-10","sc":1,"sum":"Under 18 U. S. C. §1028A(a)(1)’s crime of “aggravated identity theft,” a defendant “uses” another person’s means of identification “in relation to” a predicate offense when the use is at the crux of what makes the conduct criminal.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"32"}},{"t":"case","label":"Energy Nw. v. United States","cite":"641 F.3d 1300","y":2011,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/641/1300/","by":{"1":"7"}},{"t":"case","label":"Epic Sys. Corp. v. Lewis","cite":"584 U.S. 497","y":2018,"id":"2017/16-285","sc":1,"sum":"The Court held that the Federal Arbitration Act requires that arbitration agreements providing for individualized proceedings be enforced.","sumSrc":"Oyez","by":{"1":"43","3":"32"}},{"t":"case","label":"FAA v. Cooper","cite":"566 U.S. 284","y":2012,"id":"2011/10-1024","sc":1,"sum":"The Court held that the Privacy Act of 1974 does not cover mental and emotional distress under \"actual damages.\"","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"FCC v. ITT World Commc’ns, Inc.","cite":"466 U.S. 463","y":1984,"id":"1983/83-371","sc":1,"sum":"The Government in the Sunshine Act, 5 U. S. C. §552b(b), requires that \"meetings\" of a federal agency be open to the public. Section 552b(a)(2) defines a \"meeting\" as \"the deliberations of at least the number of individual agency members required to take action on behalf of the agency where such deliberations determine or result in the joint conduct or disposition of official agency business.\" Members of petitioner …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"20","2":"46","4":"3"}},{"t":"case","label":"Freytag v. Commissioner","cite":"501 U.S. 868","y":1991,"id":"1990/90-762","sc":1,"sum":"On the question of whether 7443A permitted the assignment of complex cases to special trial judges, the Supreme Court unanimously ruled that the statute unambiguously did allow such appointments. Justice Harry Blackmun, in the majority opinion, wrote, \"The plain language of 7443A(b)(4) surely authorizes the Chief Judge's assignment of petitioners' cases to a special trial judge.","sumSrc":"Oyez","by":{"1":"40"}},{"t":"case","label":"Huawei Techs. USA, Inc. v. FCC","cite":"2 F.4th 421","y":2021,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/2/421/","by":{"1":"24"}},{"t":"case","label":"ICC v. Brotherhood of Locomotive Eng’rs","cite":"482 U.S. 270","y":1987,"id":"1986/85-792","sc":1,"sum":"In October 1982, petitioner Interstate Commerce Commission (ICC or Commission) issued an order, which, inter alia, granted petitioner Missouri-Kansas-Texas Railroad Co. and another railroad the right to conduct operations using the tracks of a third, newly consolidated carrier. In April 1983, respondent Brotherhood of Locomotive Engineers (BLE) filed a \"Petition for Clarification\" asking the ICC to declare that the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"20","2":"46"}},{"t":"case","label":"Idaho v. U.S. Dep’t of Energy","cite":"945 F.2d 295","y":1991,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/945/295/","op":3,"by":{"1":"3","2":"2-3","3":"3, 33","5":"19"}},{"t":"case","label":"Marino v. Ortiz","cite":"484 U.S. 301","y":1988,"id":"1987/86-1415","sc":1,"op":1,"sum":"The New York City Police Department and groups representing various of its minority officers reached a settlement of the groups' employment discrimination suit under Title VII of the Civil Rights Act of 1964, which settlement was first approved by the District Court on an interim basis and, finally, after a hearing, by consent decree. Although petitionersa group of white officers claiming to be adversely affected by …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18, 29","2":"41"}},{"t":"case","label":"Michigan v. EPA","cite":"576 U.S. 743","y":2015,"id":"2014/14-46","sc":1,"op":5,"sum":"The Court determined that the Environmental Protection Agency (EPA) unreasonably interpreted the Clean Air Act by not considering costs to power plants in deciding that regulation was “appropriate and necessary.”","sumSrc":"Oyez","by":{"1":"33"}},{"t":"case","label":"National Fed’n of Indep. Bus. v. Department of Labor, Occupational Safety & Health Admin.","cite":"595 U.S. 109","y":2022,"id":"2021/21a244","sc":1,"sum":"The Court grants the applications to stay the Occupational Safety & Health Administration’s challenged rule mandating that employers with at least 100 employees require covered workers to receive a COVID–19 vaccine.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"49"}},{"t":"case","label":"Packard Elevator v. ICC","cite":"808 F.2d 654","y":1986,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/808/654/","op":1,"by":{"1":"28","5":"3"}},{"t":"case","label":"Paroline v. United States","cite":"572 U.S. 434","y":2014,"id":"2013/12-8561","sc":1,"sum":"The Court ruled that to recover restitution, either the government or the victim must establish a causal relationship between the defendant's conduct and the victim's harm or damages.","sumSrc":"Oyez","by":{"1":"33, 34"}},{"t":"case","label":"Port of Bos. Marine Terminal Ass’n v. Rederiaktiebolaget Transatlantic","cite":"400 U.S. 62","y":1970,"id":"1970/99","sc":1,"sum":"Petitioner Terminal Association, a maritime terminal operators conference. operating under an agreement approved by the Federal Maritime Commission (FMC), pursuant to §.15 of the Shipping Act, 1916, revised a tariff on file with the agency by shifting the incidence of a wharf demuri'age charge from consignees to carriers. When several carriers refused to pay the revised charge, which -had not previously been …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"25"}},{"t":"case","label":"Smith v. Bayer Corp.","cite":"564 U.S. 299","y":2011,"id":"2010/09-1205","sc":1,"sum":"The Court held that the federal court exceeded its authority under the relitigation exception to the Anti-Injunction Act when it prevented a group of plaintiffs from proceeding with a class-action lawsuit over a cholesterol-lowering drug.","sumSrc":"Oyez","by":{"1":"18","2":"41"}},{"t":"case","label":"Train v. Colorado Pub. Interest Research Grp., Inc.","cite":"426 U.S. 1","y":1976,"id":"1975/74-1270","sc":1,"sum":"The Federal Water Pollution Control Act (FWPCA) makes it unlawful to discharge \"pollutants\" into navigable waters without a permit from the Administrator of the Environmental Protection Agency (EPA), and defines the term \"pollutant\" to include, inter alia, \"radioactive materials.\" The Atomic Energy Act (AEA) regulates the production, possession, and use of three types of radioactive materials-source, byproduct, and …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"31"}},{"t":"case","label":"Truck Ins. Exch. v. Kaiser Gypsum Co.","cite":"602 U.S. 268","y":2024,"id":"2023/22-1079","sc":1,"sum":"An insurer with financial responsibility for bankruptcy claims is a “party in interest” under 11 U. S. C. §1109(b) that “may raise and may appear and be heard on any issue” in a Chapter 11 case.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"18","2":"39, 42","3":"17","4":"6"}},{"t":"case","label":"United States ex rel. Eisenstein v. City of New York","cite":"556 U.S. 928","y":2009,"id":"2008/08-660","sc":1,"op":2,"sum":"The Court held that the 30-day limit for filing a claim under the False Claims Act applies when the United States is not a party to the lawsuit.","sumSrc":"Oyez","by":{"1":"17, 29","2":"41"}},{"t":"case","label":"United States ex rel. State of Louisiana v. Jack","cite":"244 U.S. 397","y":1917,"id":"scdb/1916-100","sc":1,"sum":"The decision of the Supreme Court of Louisiana in State v. Tensas Delta Land Co., 126 Louisiana, 59, that the State had no interest or authority entitling it to intervene in a suit brought by the Tensas.Basin Levee Board for the recovery of lands which the Board had conveyed after receiving title from the State, is conclusive on this court, in the absence of any later state decision or statute modifying its effect.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"18","2":"41"}},{"t":"case","label":"Virginia Uranium, Inc. v. Warren","cite":"587 U.S. 761","y":2019,"id":"2018/16-1275","sc":1,"sum":"The Fourth Circuit’s judgment that the Atomic Energy Act does not preempt Virginia’s prohibition on uranium mining in the Commonwealth is affirmed.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"2"}},{"t":"law","label":"Pub. L. No. 96-295","url":"https://www.govinfo.gov/link/statute/94/787","by":{"1":"42","2":"3","3":"36"}},{"t":"usc","label":"5 U.S.C. § 551","url":"https://www.law.cornell.edu/uscode/text/5/551","subs":["(4)"],"by":{"1":"18, 19, 27"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","by":{"1":"18, 19","2":"43","4":"6"}},{"t":"usc","label":"42 U.S.C. § 2077","url":"https://www.law.cornell.edu/uscode/text/42/2077","subs":["(a)"],"by":{"1":"31","4":"18","5":"13"}},{"t":"usc","label":"42 U.S.C. § 2131","url":"https://www.law.cornell.edu/uscode/text/42/2131","by":{"1":"36","2":"23-24"}},{"t":"usc","label":"42 U.S.C. § 2134","url":"https://www.law.cornell.edu/uscode/text/42/2134","subs":["(a)","(b)"],"by":{"1":"36, 36"}},{"t":"usc","label":"42 U.S.C. § 2231","url":"https://www.law.cornell.edu/uscode/text/42/2231","op":1,"by":{"1":"27"}},{"t":"usc","label":"42 U.S.C. § 5842","url":"https://www.law.cornell.edu/uscode/text/42/5842","subs":["(3)"],"by":{"1":"43"}},{"t":"usc","label":"28 U.S.C. § 2341","url":"https://www.law.cornell.edu/uscode/text/28/2341","by":{"1":"8","2":"7-8, 13-14, 16, 37-39, 41, 43-45, 48","4":"1"}},{"t":"usc","label":"28 U.S.C. § 2343","url":"https://www.law.cornell.edu/uscode/text/28/2343","by":{"1":"27"}},{"t":"usc","label":"42 U.S.C. § 10131","url":"https://www.law.cornell.edu/uscode/text/42/10131","subs":["(a)(2)","(a)(7)"],"stext":{"head":"§10131. Findings and purposes","paras":[[0,"(a) The Congress finds that—"],[1,"(1) radioactive waste creates potential risks and requires safe and environmentally acceptable methods of disposal;"],[1,"(2) a national problem has been created by the accumulation of (A) spent nuclear fuel from nuclear reactors; and (B) radioactive waste from (i) reprocessing of spent nuclear fuel; (ii) activities related to medical research, diagnosis, and treatment; and (iii) other sources;"],[1,"(3) Federal efforts during the past 30 years to devise a permanent solution to the problems of civilian radioactive waste disposal have not been adequate;"],[1,"(4) while the Federal Government has the responsibility to provide for the permanent disposal of high-level radioactive waste and such spent nuclear fuel as may be disposed of in order to protect the public health and safety and the environment, the costs of such disposal should be the responsibility of the generators and owners of such waste and spent fuel;"],[1,"(5) the generators and owners of high-level radioactive waste and spent nuclear fuel have the primary responsibility to provide for, and the responsibility to pay the costs of, the interim storage of such waste and spent fuel until such waste and spent fuel is accepted by the Secretary of Energy in accordance with the provisions of this chapter;"],[1,"(6) State and public participation in the planning and development of repositories is essential in order to promote public confidence in the safety of disposal of such waste and spent fuel; and"],[1,"(7) high-level radioactive waste and spent nuclear fuel have become major subjects of public concern, and appropriate precautions must be taken to ensure that such waste and spent fuel do not adversely affect the public health and safety and the environment for this or future generations."],[0,"(b) The purposes of this part are—"],[1,"(1) to establish a schedule for the siting, construction, and operation of repositories that will provide a reasonable assurance that the public and the environment will be adequately protected from the hazards posed by high-level radioactive waste and such spent nuclear fuel as may be disposed of in a repository;"],[1,"(2) to establish the Federal responsibility, and a definite Federal policy, for the disposal of such waste and spent fuel;"],[1,"(3) to define the relationship between the Federal Government and the State governments with respect to the disposal of such waste and spent fuel; and"],[1,"(4) to establish a Nuclear Waste Fund, composed of payments made by the generators and owners of such waste and spent fuel, that will ensure that the costs of carrying out activities relating to the disposal of such waste and spent fuel will be borne by the persons responsible for generating such waste and spent fuel."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/10131?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§10131. Findings and purposes","tname":"The Public Health and Welfare","by":{"1":"5, 44","2":"5, 25, 25","5":"18"}},{"t":"usc","label":"5 U.S.C. § 1508","url":"https://www.law.cornell.edu/uscode/text/5/1508","by":{"1":"17"}},{"t":"usc","label":"8 U.S.C. § 1252","url":"https://www.law.cornell.edu/uscode/text/8/1252","subs":["(a)(1)"],"by":{"1":"8"}},{"t":"usc","label":"12 U.S.C. § 1848","url":"https://www.law.cornell.edu/uscode/text/12/1848","by":{"1":"17"}},{"t":"usc","label":"19 U.S.C. § 2395","url":"https://www.law.cornell.edu/uscode/text/19/2395","by":{"1":"17"}},{"t":"usc","label":"42 U.S.C. § 2000e-16c","url":"https://www.law.cornell.edu/uscode/text/42/2000e-16c","subs":["(c)"],"by":{"1":"8"}},{"t":"reg","label":"40 Fed. Reg. 42,801","url":"https://www.govinfo.gov/link/fr/40/42801","by":{"1":"38","2":"2, 28, 35"}},{"t":"reg","label":"42 Fed. Reg. 34,391","url":"https://www.govinfo.gov/link/fr/42/34391","by":{"1":"47"}},{"t":"reg","label":"56 Fed. Reg. 55,695","url":"https://www.govinfo.gov/link/fr/56/55695","by":{"1":"37"}},{"t":"reg","label":"83 Fed. Reg. 44,070","url":"https://www.govinfo.gov/link/fr/83/44070","by":{"1":"8, 9"}},{"t":"reg","label":"86 Fed. Reg. 51,926","url":"https://www.govinfo.gov/link/fr/86/51926","by":{"1":"10"}},{"t":"reg","label":"87 Fed. Reg. 56,987","url":"https://www.govinfo.gov/link/fr/87/56987","by":{"1":"37"}},{"t":"case","label":"Abbott Labs. v. Gardner","cite":"387 U.S. 136","y":1967,"id":"1966/39","sc":1,"op":2,"ar":1,"sum":"The Court found that congress did not intend to forbid pre-enforcement review of regulations like the \"every time\" rule. The legislature designed the statute's specific review provisions to provide additional remedies for parties in Abbott Laboratories' position, not to cut down traditional channels of review. The Court remanded the case to the court of appeals.","sumSrc":"Oyez","by":{"2":"44-45, 48","5":"8-9"}},{"t":"case","label":"AMG Cap. Mgmt., LLC v. FTC","cite":"593 U.S. 67","y":2021,"url":"https://supreme.justia.com/cases/federal/us/593/67/","sc":1,"by":{"2":"36-37"}},{"t":"case","label":"Baros v. Texas Mexican Ry. Co.","cite":"400 F.3d 228","y":2005,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/400/228/","by":{"2":"47"}},{"t":"case","label":"Comuni-Centre Broad., Inc. v. FCC","cite":"856 F.2d 1551","y":1988,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/856/1551/","by":{"2":"40"}},{"t":"case","label":"Desert Palace, Inc. v. Costa","cite":"539 U.S. 90","y":2003,"id":"2002/02-679","sc":1,"sum":"The Court held that direct evidence is not required.","sumSrc":"Oyez","by":{"2":"38"}},{"t":"case","label":"Duncan v. Walker","cite":"533 U.S. 167","y":2001,"id":"2000/00-121","sc":1,"op":1,"sum":"The Court held that an federal habeas corpus petition is not an \"application for State post-conviction or other collateral review\" within the meaning of 28 USC section 2244(d)(2). \"Section 2244(d)(2) therefore did not toll the limitation period during the pendency of [Walker's] first federal habeas petition,\" wrote Justice O'Connor. \"[I]f the statute were construed so as to give applications for federal review the same tolling effect as applications for state collateral review, then [section] 2244(d)(2) would furnish little incentive for individuals to seek relief from the state courts before filing federal habeas petitions,\" concluded Justice O'Connor.","sumSrc":"Oyez","by":{"2":"27"}},{"t":"case","label":"Edward Hines Yellow Pine Tr. v. United States","cite":"263 U.S. 143","y":1923,"id":"scdb/1923-021","sc":1,"sum":"1. To maintain a suit to set aside an order of the Interstate Commerce Commission upon the ground that it exceeded the powers of the Commission, it is not essential that a plaintiff should have been a party to the proceedings before the Commission in which the order was made.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"44","5":"9"}},{"t":"case","label":"FDA v. Brown & Williamson Tobacco Corp.","cite":"529 U.S. 120","y":2000,"id":"1999/98-1152","sc":1,"sum":"The Court held that \"Congress has not given the FDA the authority to regulate tobacco products as customarily marketed.\" The ruling was based on the FDCA as a whole and in conjunction with Congress' subsequent tobacco-specific legislation. \"By no means do we question the seriousness of the problem that the FDA has sought to address,\" Justice O'Connor wrote for the majority.","sumSrc":"Oyez","by":{"2":"22, 25","3":"31-32, 33, 36, 37"}},{"t":"case","label":"Florida Power & Light Co. v. Lorion","cite":"470 U.S. 729","y":1985,"id":"1984/83-703","sc":1,"sum":"Section 2239 vests in the courts of appeals initial subject-matter jurisdiction over Commission orders denying citizen petitions made pursuant to Commission rules.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"41","3":"12, 15, 23"}},{"t":"case","label":"Florida Power & Light Co. v. Westinghouse Elec. Corp.","cite":"826 F.2d 239","y":1987,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/826/239/","by":{"2":"28","3":"32"}},{"t":"case","label":"Illinois v. General Elec. Co.","cite":"683 F.2d 206","y":1982,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/683/206/","by":{"2":"2","3":"44, 45, 47"}},{"t":"case","label":"Lexecon Inc. v. Milberg Weiss Bershad Hynes & Lerach","cite":"523 U.S. 26","y":1998,"id":"1997/96-1482","sc":1,"sum":"The Court held that a district court conducting pretrial proceedings pursuant to section 1407(a) has no authority to invoke section 1404(a) to assign a transferred case to itself for trial.","sumSrc":"Oyez","by":{"2":"39"}},{"t":"case","label":"Massachusetts v. NRC","cite":"878 F.2d 1516","y":1989,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/878/1516/","by":{"2":"41"}},{"t":"case","label":"NARUC v. DOE","cite":"736 F.3d 517","y":2013,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/736/517/","by":{"2":"20","3":"4"}},{"t":"case","label":"PDR Network, LLC v. Carlton & Harris Chiropractic, Inc.","cite":"588 U.S. 1","y":2019,"id":"2018/17-1705","sc":1,"sum":"The Court held that Fourth Circuit did not properly consider preliminary issues that determine whether a district court must accept the Federal Communication Commission's legal interpretation of the Telephone Consumer Protection Act.","sumSrc":"Oyez","by":{"2":"38, 42, 44","5":"6"}},{"t":"case","label":"Posadas v. National City Bank of New York","cite":"296 U.S. 497","y":1936,"id":"scdb/1935-071","sc":1,"by":{"2":"22"}},{"t":"case","label":"Pulsifer v. United States","cite":"601 U.S. 124","y":2024,"id":"2023/22-340","sc":1,"sum":"A criminal defendant facing a mandatory minimum sentence is eligible for safety-valve relief under 18 U. S. C. §3553(f)(1) only if the defendant satisfies each of the provision’s three conditions.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"26","3":"38"}},{"t":"case","label":"Radiofone, Inc. v. FCC","cite":"759 F.2d 936","y":1985,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/759/936/","by":{"2":"48"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"29"}},{"t":"case","label":"Skinner & Eddy Corp. v. United States","cite":"249 U.S. 557","y":1919,"id":"scdb/1918-106","sc":1,"sum":"Where a suit to enjoin the enforcement of an. order of the Interstate Commerce Commission is based upon the ground that the order exceeded the statutory powers of the Commission and, hence, is void, the courts may entertain jurisdiction notwithstanding no attempt has been made by the plaintiff to obtain redress from the Commission itself.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"44","5":"9"}},{"t":"case","label":"United States v. Cotton","cite":"535 U.S. 625","y":2002,"id":"2001/01-687","sc":1,"sum":"The Court held that the omission from a federal indictment of a fact that enhances the statutory maximum sentence does not justify a Court of Appeals' vacating the enhanced sentence, even though the defendant did not object in the trial court.","sumSrc":"Oyez","by":{"2":"43"}},{"t":"case","label":"United States v. Fausto","cite":"484 U.S. 439","y":1988,"id":"1987/86-595","sc":1,"sum":"The CSRA, which affords to nonpreference eligibles in the excepted service no administrative or judicial review of adverse personnel action of the type involved here, precludes judicial review for those employees under the Tucker Act based on the Back Pay Act. The CSRA was designed to replace the haphazard arrangements that had built up over almost a century with one integrated system for administrative and judicial …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"22","5":"21"}},{"t":"case","label":"Utility Air Regulatory Grp. v. EPA","cite":"573 U.S. 302","y":2014,"id":"2013/12-1146","sc":1,"sum":"The Court held that, under the Clean Air Act, the EPA is not required to include greenhouse gas emissions every time it mentions air pollution.","sumSrc":"Oyez","by":{"2":"33","3":"31, 33, 35"}},{"t":"case","label":"Yates v. United States","cite":"574 U.S. 528","y":2015,"id":"2014/13-7451","sc":1,"op":1,"sum":"The Court ruled that a “tangible item” as defined by Section 1519 of the Sarbanes-Oxley Act is one used to record or preserve information.","sumSrc":"Oyez","by":{"2":"30-31"}},{"t":"usc","label":"28 U.S.C. § 2346","url":"https://www.law.cornell.edu/uscode/text/28/2346","by":{"2":"13"}},{"t":"usc","label":"42 U.S.C. § 2021b","url":"https://www.law.cornell.edu/uscode/text/42/2021b","subs":["(9)(A)(i)"],"by":{"2":"24"}},{"t":"usc","label":"42 U.S.C. § 2065","url":"https://www.law.cornell.edu/uscode/text/42/2065","subs":["(c)(3)"],"by":{"2":"24"}},{"t":"usc","label":"42 U.S.C. § 2160","url":"https://www.law.cornell.edu/uscode/text/42/2160","by":{"2":"24"}},{"t":"usc","label":"42 U.S.C. § 2210h","url":"https://www.law.cornell.edu/uscode/text/42/2210h","subs":["(a)(2)(B)"],"by":{"2":"24"}},{"t":"usc","label":"42 U.S.C. § 2210i","url":"https://www.law.cornell.edu/uscode/text/42/2210i","subs":["(a)","(b)"],"by":{"2":"24, 27","4":"13, 13"}},{"t":"usc","label":"42 U.S.C. § 2284","url":"https://www.law.cornell.edu/uscode/text/42/2284","subs":["(a)(3)"],"by":{"2":"24"}},{"t":"law","label":"Pub. L. No. 109-58","url":"https://www.govinfo.gov/link/plaw/109/public/58","by":{"2":"3"}},{"t":"usc","label":"15 U.S.C. § 53","url":"https://www.law.cornell.edu/uscode/text/15/53","subs":["(b)"],"by":{"2":"36"}},{"t":"usc","label":"21 U.S.C. § 301","url":"https://www.law.cornell.edu/uscode/text/21/301","by":{"2":"44"}},{"t":"usc","label":"42 U.S.C. § 10132","url":"https://www.law.cornell.edu/uscode/text/42/10132","op":1,"by":{"2":"5"}},{"t":"usc","label":"42 U.S.C. § 10134","url":"https://www.law.cornell.edu/uscode/text/42/10134","subs":["(b)","(d)"],"by":{"2":"5, 5, 5, 23","4":"20"}},{"t":"usc","label":"42 U.S.C. § 10152","url":"https://www.law.cornell.edu/uscode/text/42/10152","by":{"2":"18, 20","4":"18","5":"18"}},{"t":"usc","label":"42 U.S.C. § 10153","url":"https://www.law.cornell.edu/uscode/text/42/10153","by":{"2":"18, 21, 23","4":"18","5":"18"}},{"t":"usc","label":"42 U.S.C. § 10154","url":"https://www.law.cornell.edu/uscode/text/42/10154","subs":["(a)"],"by":{"2":"18","4":"18, 19","5":"18"}},{"t":"usc","label":"42 U.S.C. § 10172","url":"https://www.law.cornell.edu/uscode/text/42/10172","stext":{"head":"§10172. Selection of Yucca Mountain site","paras":[[0,"(a) In general"],[0,"(1) The Secretary shall provide for an orderly phase-out of site specific activities at all candidate sites other than the Yucca Mountain site."],[0,"(2) The Secretary shall terminate all site specific activities (other than reclamation activities) at all candidate sites, other than the Yucca Mountain site, within 90 days after December 22, 1987."],[0,"(b) Eligibility to enter into benefits agreement"],[0,"Effective on December 22, 1987, the State of Nevada shall be eligible to enter into a benefits agreement with the Secretary under section 10173 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/10172?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§10172. Selection of Yucca Mountain site","tname":"The Public Health and Welfare","by":{"2":"5"}},{"t":"law","label":"Pub. L. No. 100-408","url":"https://www.govinfo.gov/link/statute/102/1066","by":{"2":"3, 24"}},{"t":"usc","label":"28 U.S.C. § 2112","url":"https://www.law.cornell.edu/uscode/text/28/2112","subs":["(a)(1)"],"by":{"2":"13"}},{"t":"case","label":"Br. for Resp. U.S. Nuclear Regulatory Comm’n, Bullcreek v. NRC","cite":"2003 WL 25588879","y":2003,"court":"D.C. Cir. Oct. 1","by":{"2":"35"}},{"t":"case","label":"Abramski v. United States","cite":"573 U.S. 169","y":2014,"id":"2013/12-1493","sc":1,"sum":"The Court held that a firearm purchaser's intent to sell their gun to another buyer is necessary information for the seller's records.","sumSrc":"Oyez","by":{"3":"9"}},{"t":"case","label":"Ala. Ass’n of Realtors v. HHS","cite":"594 U.S. 758","y":2021,"url":"https://supreme.justia.com/cases/federal/us/594/758/","sc":1,"by":{"3":"31, 34-35"}},{"t":"case","label":"Am. Bar Ass’n v. FTC","cite":"430 F.3d 457","y":2005,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/430/457/","by":{"3":"34"}},{"t":"case","label":"Am. Bus. Ass’n v. Slater","cite":"231 F.3d 1","y":2000,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/231/1/","by":{"3":"25"}},{"t":"case","label":"Am. Hosp. Ass’n. v. Becerra","cite":"596 U.S. 724","y":2022,"url":"https://supreme.justia.com/cases/federal/us/596/724/","sc":1,"by":{"3":"46"}},{"t":"case","label":"Atl. City Elec. Co. v. FERC","cite":"295 F.3d 1","y":2002,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/295/1/","by":{"3":"34"}},{"t":"case","label":"Bates & Guild Co. v. Payne","cite":"194 U.S. 106","y":1904,"id":"scdb/1903-143","sc":1,"sum":"Where the decision of questions of fact is committed by Congress to the judgment and discretion of the head of a department, his decision thereon is conclusive; and even upon mixed questions of law and fact, or of law alone, his action will carry with it a strong presumption of its correctness, and the courts will-not ordinarily review it, although they have the power,. and will occasionally exercise the right of so …","sumSrc":"Headnote (U.S. Reports)","by":{"3":"22"}},{"t":"case","label":"Biden v. Nebraska","cite":"143 S. Ct. 2355","y":2023,"id":"2022/22-506","sc":1,"sum":"The Secretary of Education does not have authority under the Higher Education Relief Opportunities for Students Act of 2003 (HEROES Act) to establish a student loan forgiveness program that will cancel roughly $430 billion in debt principal and affect nearly all borrowers.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"31, 32, 34","5":"22"}},{"t":"case","label":"Brnovich v. Democratic Nat’l Comm.","cite":"594 U.S. 647","y":2021,"id":"2020/19-1257","sc":1,"sum":"Arizona’s challenged voting regulations governing precinct-based election-day voting (rejecting ballots cast in the wrong precinct) and early mail-in voting (making it a crime for anyone other than an authorized proxy to possess the early ballot of another voter) do not violate §2 of the Voting Rights Act of 1965; Arizona House Bill 2023 (enacting the early mail-in voting regulations) was not enacted with a racially discriminatory purpose.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"9"}},{"t":"case","label":"Brown v. Gardner","cite":"513 U.S. 115","y":1994,"id":"1994/93-1128","sc":1,"sum":"The Court affirmed the lower court's decision and ruled for Gardner. The Court held that Section 1151 contains no language requiring proof of fault, and it rejected the Government's claims that the requirement was implicit in the language of the statute.","sumSrc":"Oyez","by":{"3":"20"}},{"t":"case","label":"Carlyle Towers Condo. Ass’n, Inc. v. F.D.I.C.","cite":"170 F.3d 301","y":1999,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/170/301/","by":{"3":"13"}},{"t":"case","label":"Carr v. Saul","cite":"593 U.S. 83","y":2021,"id":"2020/19-1442","sc":1,"sum":"Principles of issue-exhaustion do not require Social Security disability claimants to argue at the agency level that the administrative law judges hearing their disability claims were unconstitutionally appointed.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"20"}},{"t":"case","label":"Chevron U.S.A., Inc. v. NRDC, Inc.","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"op":4,"sum":"The Supreme Court held that the bubble regulation was a reasonable interpretation of the term “stationary source” in the Clean Air Act. Congress did not have a specific intention for the interpretation of that term, and the EPA’s regulation was a reasonable policy choice. The regulation also provided reasonable accommodations for the many competing interests affected by the Act.","sumSrc":"Oyez","by":{"3":"20, 42"}},{"t":"case","label":"Circuit City Stores, Inc. v. Adams","cite":"532 U.S. 105","y":2001,"id":"2000/99-1379","sc":1,"op":54,"ar":36,"sum":"The Court held that section 1 exemption is confined to transportation workers. \"The wording of [section 1] calls for the application of the maxim ejusdem generis, the statutory canon that 'where general words follow specific words in a statutory enumeration, the general words are construed to embrace only objects similar in nature to those objects enumerated by the preceding specific words,'\" wrote Justice Kennedy.","sumSrc":"Oyez","by":{"3":"27-28"}},{"t":"case","label":"County of Rockland v. NRC","cite":"709 F.2d 766","y":1983,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/709/766/","by":{"3":"2, 37"}},{"t":"case","label":"Darby v. Cisneros","cite":"509 U.S. 137","y":1993,"id":"1992/91-2045","sc":1,"sum":"Federal courts do not have the authority to require a plaintiff to exhaust available administrative remedies before seeking judicial review under the APA, where neither the relevant statute nor agency rules specifically mandate exhaustion as a prerequisite to judicial review. The language of § 10(c) of the APA is explicit that an appeal to \"superior agency authority\" is a prerequisite to judicial review only when …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"10, 18","4":"6","5":"4"}},{"t":"case","label":"Dep’t of Com. v. New York","cite":"588 U.S. 752","y":2019,"url":"https://supreme.justia.com/cases/federal/us/588/752/","sc":1,"by":{"3":"29"}},{"t":"case","label":"DeVillier v. Texas","cite":"601 U.S. 285","y":2024,"id":"2023/22-913","sc":1,"sum":"Owners of property north of U. S. Interstate Highway 10 adversely affected by the flood evacuation barrier constructed by Texas should be permitted on remand to pursue their Takings Clause claims through the cause of action available under Texas law.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"21","5":"8"}},{"t":"case","label":"DHS v. MacLean","cite":"574 U.S. 383","y":2015,"id":"2014/13-894","sc":1,"sum":"The Court ruled that the Whistleblower Protection Act bars an agency from taking enforcement action against employees who intentionally disclose sensitive security information.","sumSrc":"Oyez","by":{"3":"39"}},{"t":"case","label":"Env’t Def. v. Duke Energy Corp.","cite":"549 U.S. 561","y":2007,"id":"2006/05-848","sc":1,"sum":"Unanswered and No. In a unanimous opinion by Justice David Souter, the Court ruled that the EPA need not interpret \"modification\" in PSD regulations the same way the term is interpreted in NSPS regulations. The Court's opinion acknowledged that two occurrences of the same term - sharing the same definition - are normally given the same meaning.","sumSrc":"Oyez","by":{"3":"17"}},{"t":"case","label":"Erlenbaugh v. United States","cite":"409 U.S. 239","y":1972,"id":"1972/71-839","sc":1,"sum":"Causing a publication to be carried by a facility of interstate commerce with an intent to facilitate the operation of an illegal gambling business is a violation of 18 U. S. C. § 1952. The exception for \"any newspaper or similar publication\" contained in 18 U. S. C. § 1953, which prohibits the interstate shipment of certain gambling paraphernalia, was not intended to be read into § 1952. Pp. 242-248. 452 F. 2d 967, …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"28"}},{"t":"case","label":"Ethyl Corp. v. EPA","cite":"51 F.3d 1053","y":1995,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/51/1053/","by":{"3":"34"}},{"t":"case","label":"Fed. Express Corp. v. U.S Dep’t of Com.","cite":"39 F.4th 756","y":2022,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/39/756/","by":{"3":"22, 23","5":"9"}},{"t":"case","label":"Fischer v. United States","cite":"603 U.S. 480","y":2024,"id":"2023/23-5572","sc":1,"op":1,"sum":"The Court held that 18 U.S.C. § 1512(c), which prohibits obstruction of congressional inquiries and investigations, does not include acts unrelated to investigations and evidence.","sumSrc":"Oyez","by":{"3":"27, 40, 41"}},{"t":"case","label":"Gundy v. United States","cite":"588 U.S. 128","y":2019,"id":"2018/17-6086","sc":1,"sum":"The Second Circuit’s judgment that 34 U. S. C. §20913(d)—which requires the Attorney General to apply the Sex Offender Registration and Notification Act’s registration requirements as soon as feasible to offenders convicted before the statute’s enactment—is not an unconstitutional delegation of legislative authority is affirmed.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"25"}},{"t":"case","label":"Hamer v. Neighborhood Housing Servs. of Chi.","cite":"583 U.S. 17","y":2017,"id":"2017/16-658","sc":1,"sum":"A case in which Court held that Federal Rule of Appellate Procedure 4(a)(5)(C), which places a time limit on appeals, is not jurisdictional because it is a court-made rule rather than a statute.","sumSrc":"Oyez","by":{"3":"13"}},{"t":"case","label":"Heating, Air Conditioning & Refrigeration Distribs. Int’l v. EPA","cite":"71 F.4th 59","y":2023,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/71/59/","by":{"3":"32"}},{"t":"case","label":"Hertz Corp. v. Friend","cite":"559 U.S. 77","y":2010,"id":"2009/08-1107","sc":1,"sum":"The Court held that the court system cannot disregard the location of a corporation's principal place of business in a multi-state lawsuit.","sumSrc":"Oyez","by":{"3":"15"}},{"t":"case","label":"Illinois v. NRC","cite":"591 F.2d 12","y":1979,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/591/12/","by":{"3":"47"}},{"t":"case","label":"Jersey Cent. Power & Light Co. v. Township of Lacey","cite":"772 F.2d 1103","y":1985,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/772/1103/","by":{"3":"44-45, 47"}},{"t":"case","label":"Kentucky v. Biden","cite":"23 F.4th 585","y":2022,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/23/585/","sum":"Rejecting a similar theory based on Sturgeon.","sumSrc":"brief:3","by":{"3":"41"}},{"t":"case","label":"Knick v. Township of Scott","cite":"588 U.S. 180","y":2019,"id":"2018/17-647","sc":1,"sum":"A government violates the Takings Clause when it takes property without compensation, and a property owner may bring a Fifth Amendment claim under 42 U. S. C. §1983 at that time; the state-litigation requirement of Williamson County Regional Planning Comm’n v. Hamilton Bank of Johnson City, 473 U. S. 172, is overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"21-22","5":"9"}},{"t":"case","label":"Kucana v. Holder","cite":"558 U.S. 233","y":2010,"id":"2009/08-911","sc":1,"op":1,"sum":"The Court held that 8 U.S.C. Section 1252(a)(2)(B)(ii) does not preclude federal courts from hearing cases specified by the Attorney General, only cases that are specified by statute.","sumSrc":"Oyez","by":{"3":"13, 14, 15"}},{"t":"case","label":"La. Pub. Serv. Comm’n v. FCC","cite":"476 U.S. 355","y":1986,"id":"1985/84-871","sc":1,"sum":"Section 152(b) bars federal pre-emption of state regulation over depreciation of dual jurisdiction property for intrastate ratemaking purposes.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"8, 34"}},{"t":"case","label":"Larson v. Domestic & Foreign Com. Corp.","cite":"337 U.S. 682","y":1949,"id":"scdb/1948-106","sc":1,"sum":"The suit was one against the United States 4nd, in the absence of consent by the United States, the District Court was without jurisdiction. Pp. 684-705. 2.' In determining whether a suit nominally against an officer is against the officer individually or against the sovereign, the crucial qukestion is whether the relief sought is relief against the sovereign. Pp. 687-688. Statement of the Case.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"22, 23"}},{"t":"case","label":"Lujan v. Nat’l Wildlife Fed’n","cite":"497 U.S. 871","y":1990,"id":"1989/89-640","sc":1,"sum":"In a 5-to-4 decision written by Justice Antonin Scalia, the Supreme Court held that NWF did not have standing to challenge the land-use designations. The two timely affidavits were not enough to show that the group members had actually been affected by the BLM decisions.","sumSrc":"Oyez","by":{"3":"18","4":"6"}},{"t":"case","label":"Marx v. Gen. Revenue Corp.","cite":"568 U.S. 371","y":2013,"id":"2012/11-1175","sc":1,"sum":"The Court held that the Federal Rules of Civil Procedure awards costs to the prevailing party unless a statute explicitly states otherwise.","sumSrc":"Oyez","by":{"3":"26"}},{"t":"case","label":"McCarthy v. Madigan","cite":"503 U.S. 140","y":1992,"id":"1991/90-6861","sc":1,"sum":"Exhaustion of the Bureau of Prisons' administrative procedure is not required before a federal prisoner can initiate a Bivens action solely for money damages.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"20"}},{"t":"case","label":"MCI Telecomms. Corp. v. AT&T Co.","cite":"512 U.S. 218","y":1994,"id":"1993/93-356","sc":1,"sum":"The Commission's permissive detariffing policy is not a valid exercise of its §203(b)(2) authority to \"modify any requirement.\" Because virtually every dictionary in use now and at the time the statute was enacted defines \"to modify\" as meaning to change moderately or in minor fashion, the word \"modify\" must be seen to have a connotation of increment or limitation. That § 203(b)(2) does not contemplate basic or …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"32"}},{"t":"case","label":"Nat’l Ass’n of Home Builders v. U.S. Army Corps of Eng’rs","cite":"417 F.3d 1272","y":2005,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/417/1272/","by":{"3":"15"}},{"t":"case","label":"Neustar, Inc. v. FCC","cite":"857 F.3d 886","y":2017,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/857/886/","by":{"3":"15"}},{"t":"case","label":"New York v. NRC","cite":"681 F.3d 471","y":2012,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/681/471/","by":{"3":"3, 29"}},{"t":"case","label":"NRDC v. NRC","cite":"582 F.2d 166","y":1978,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/582/166/","by":{"3":"32"}},{"t":"case","label":"Qwest Servs. Corp. v. FCC","cite":"509 F.3d 531","y":2007,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/509/531/","by":{"3":"16"}},{"t":"case","label":"RadLAX Gateway Hotel, LLC v. Amalgamated Bank","cite":"566 U.S. 639","y":2012,"id":"2011/11-166","sc":1,"sum":"The Court held that a company could not obtain confirmation of a Chapter 11 bankruptcy plan that provided for the sale of its assets free from lien without permitting a bank to credit-bid at the sale.","sumSrc":"Oyez","by":{"3":"32, 35"}},{"t":"case","label":"Rapanos v. United States","cite":"547 U.S. 715","y":2006,"id":"2005/04-1034","sc":1,"sum":"The plurality rejected the argument that only actually-navigable waters can be regulated by the Clean Water Act, but also held that the word \"navigable\" in the Act cannot be divested of all meaning. The plurality held that the definitional term \"waters of the United States\" can only refer to \"relatively permanent, standing or flowing bodies of water,\" not \"occasional,\" \"intermittent,\" or \"ephemeral\" flows.","sumSrc":"Oyez","by":{"3":"43, 46"}},{"t":"case","label":"Richman Bros. Records, Inc. v. FCC","cite":"124 F.3d 1302","y":1997,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/124/1302/","by":{"3":"14"}},{"t":"case","label":"Rodriguez v. United States","cite":"480 U.S. 522","y":1987,"id":"1986/86-5504","sc":1,"sum":"Section 3147 does not divest sentencing judges of their § 3651 authority. Nothing in the language of the two provisions suggests the existence of an \"irreconcilable conflict\" from which an intent to work an implicit partial repeal of § 3651 may be inferred; to the contrary, the provisions fit together quite sensibly. Moreover, the totality of the legislative history of the Act of which §3147 is a part demonstrates …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"38"}},{"t":"case","label":"S. Cal. Edison Co. v. United States","cite":"93 Fed. Cl. 337","y":2010,"court":"Fed. Cl.","url":"https://www.courtlistener.com/c/Fed.%20Cl./93/337/","by":{"3":"47"}},{"t":"case","label":"Salinas v. U.S. R.R. Ret. Bd.","cite":"592 U.S. 188","y":2021,"url":"https://supreme.justia.com/cases/federal/us/592/188/","sc":1,"by":{"3":"12"}},{"t":"case","label":"Santos-Zacaria v. Garland","cite":"598 U.S. 411","y":2023,"id":"2022/21-1436","sc":1,"sum":"Title 8 U. S. C. §1252(d)(1)—which requires noncitizens to “exhaus[t] all administrative remedies . . . as of right” before challenging a Board of Immigration Appeals final order of removal in federal court—is not a jurisdictional provision and does not require noncitizens to request discretionary forms of review.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"15"}},{"t":"case","label":"SAS Inst., Inc. v. Iancu","cite":"584 U.S. 357","y":2018,"id":"2017/16-969","sc":1,"sum":"The Court decided that when the United States Patent and Trademark Office institutes an inter partes review to reconsider an already-issued patent claim, under 35 U.S.C. §§ 311-319, it must decide the patentability of all of the claims the petitioner has challenged.","sumSrc":"Oyez","by":{"3":"39"}},{"t":"case","label":"SEC v. Chenery Corp.","cite":"332 U.S. 194","y":1947,"id":"scdb/1946-133","sc":1,"sum":"The new order is sustained. Pp. 196-199, 209.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"15"}},{"t":"case","label":"Steel Co. v. Citizens for Better Env’t","cite":"523 U.S. 83","y":1998,"id":"1997/96-643","sc":1,"op":1,"sum":"The Court held, because none of the relief sought would likely remedy its alleged injury in fact, that Citizens For A Better Environment lacked standing to maintain suit and that the Court and lower federal courts lack the jurisdiction to entertain it. While all nine Justices agreed that the organization lacked standing, they disagreed on the reasons.","sumSrc":"Oyez","by":{"3":"16"}},{"t":"case","label":"Sturgeon v. Frost","cite":"587 U.S. 28","y":2019,"id":"2018/17-949","sc":1,"sum":"Alaska’s Nation River is not public land; and like all non-public lands and navigable waters within Alaska’s national parks, it is exempt under the Alaska National Interest Lands Conservation Act from the National Park Service’s ordinary regulatory authority.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"37, 41","5":"16"}},{"t":"case","label":"United States v. Lee","cite":"106 U.S. 196","y":1882,"id":"scdb/1882-052","sc":1,"by":{"3":"21"}},{"t":"case","label":"United States v. Sineneng-Smith","cite":"590 U.S. 371","y":2020,"id":"2019/19-67","sc":1,"sum":"The Court held that the Ninth Circuit’s decision below was an abuse of discretion because it considered and ruled on an issue not raised by the parties.","sumSrc":"Oyez","by":{"3":"45"}},{"t":"case","label":"United States v. Stewart","cite":"311 U.S. 60","y":1940,"id":"scdb/1940-007","sc":1,"by":{"3":"28, 36"}},{"t":"case","label":"United States v. Texas","cite":"507 U.S. 529","y":1993,"id":"1992/91-1729","sc":1,"sum":"The Act left in place the States' federal common-law obligation to pay prejudgment interest on debts owed to the Federal Government.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"23"}},{"t":"case","label":"Vt. Yankee Nuclear Power Corp. v. NRDC, Inc.","cite":"435 U.S. 519","y":1978,"id":"1977/76-419","sc":1,"sum":"In No. 76-419, after extensive hearings before the Atomic Safety and Licensing Board (Licensing Board) and over respondents' objections, the Atomic Energy Commission (AEC) granted petitioner Vermont Yankee Nuclear Power Corp. a license to operate a nuclear power plant, and this ruling was affirmed by the Atomic Safety and Licensing Appeal Board (Appeal Board). Subsequently, the AEC, specifically referring to the …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"10, 15"}},{"t":"case","label":"Whitman v. Am. Trucking Ass’ns","cite":"531 U.S. 457","y":2001,"id":"2000/99-1257","sc":1,"sum":"The Court held that the CAA properly delegated legislative power to the EPA, but that the EPA could not consider implementation costs in setting primary and secondary NAAQS.","sumSrc":"Oyez","by":{"3":"14, 32"}},{"t":"case","label":"Youngstown Sheet & Tube Co. v. Sawyer","cite":"343 U.S. 579","y":1952,"id":"1940-1955/343us579","sc":1,"sum":"The Court held that the President did not have the right to seize control of most of the country's steel mills to negate the effects of a suspected strike during the Korean War.","sumSrc":"Oyez","by":{"3":"22"}},{"t":"usc","label":"15 U.S.C. § 717r","url":"https://www.law.cornell.edu/uscode/text/15/717r","subs":["(a)"],"by":{"3":"14"}},{"t":"case","label":"Other Authorities— Continued: Oral Argument, Texas v. NRC","cite":"78 F.4th 827","y":2023,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/78/827/","op":4,"by":{"3":"45"}},{"t":"case","label":"Harrow v. Department of Def.","cite":"601 U.S. 480","y":2024,"id":"2023/23-21","sc":1,"sum":"Title 5 U. S. C. §7703(b)(1)’s 60-day filing deadline for a federal employee to petition the Federal Circuit to review a final decision of the Merit Systems Protection Board is not jurisdictional.","sumSrc":"Holding (supremecourt.gov)","by":{"4":"10"}},{"t":"case","label":"Ross v. Blake","cite":"578 U.S. 632","y":2016,"id":"2015/15-339","sc":1,"sum":"The Court determined that the Prison Litigation Reform Act’s requirement to exhaust administrative remedies does not have a “special circumstances” exception.","sumSrc":"Oyez","by":{"4":"10"}},{"t":"case","label":"Thunder Basin Coal Co. v. Reich","cite":"510 U.S. 200","y":1994,"id":"1993/92-896","sc":1,"sum":"Petitioner mine operator's nonunion work force designated two employees of the United Mine Workers of America (UMWA) to serve as miners' representatives under 30 U. S. C. §813(f). Claiming that the designations compromised its rights under the National Labor Relations Act (NLRA), petitioner refused to post information about the representatives as required by a regulation issued by the Department of Labor's Mine …","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"3"}},{"t":"usc","label":"42 U.S.C. § 10136","url":"https://www.law.cornell.edu/uscode/text/42/10136","by":{"4":"22"}},{"t":"usc","label":"42 U.S.C. § 10156","url":"https://www.law.cornell.edu/uscode/text/42/10156","subs":["(e)","(a)(1)"],"by":{"4":"22","5":"18"}},{"t":"usc","label":"42 U.S.C. § 10166","url":"https://www.law.cornell.edu/uscode/text/42/10166","by":{"4":"22"}},{"t":"usc","label":"42 U.S.C. § 10169","url":"https://www.law.cornell.edu/uscode/text/42/10169","by":{"4":"22"}},{"t":"usc","label":"28 U.S.C. § 1331","url":"https://www.law.cornell.edu/uscode/text/28/1331","by":{"4":"4"}},{"t":"rule","label":"Fed. R. Civ. P. 24","url":"https://www.law.cornell.edu/rules/frcp/rule_24","by":{"4":"6"}},{"t":"reg","label":"55 Fed. Reg. 29,181","url":"https://www.govinfo.gov/link/fr/55/29181","by":{"4":"18"}},{"t":"case","label":"Alaska v. FERC","cite":"980 F.2d 761","y":1992,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/980/761/","by":{"5":"7"}},{"t":"case","label":"Blue Ridge Env’t Def. League v. NRC","cite":"716 F.3d 183","y":2013,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/716/183/","ar":2,"by":{"5":"6"}},{"t":"case","label":"Edelman v. Lynchburg Coll.","cite":"535 U.S. 106","y":2002,"id":"2001/00-1072","sc":1,"sum":"The Court held that the EEOC's relation-back regulation was an unassailable interpretation of Title VII of the Civil Rights Act of 1964.","sumSrc":"Oyez","by":{"5":"19"}},{"t":"case","label":"F. Hoffman-La Roche Ltd. v. Empagran S.A.","cite":"542 U.S. 155","y":2004,"id":"2003/03-724","sc":1,"sum":"The Court unanimously ruled that Congress' intent in passing the FTAIA was to prevent American courts from interfering in foreign commerce. Congress made an exception for foreign commerce that affected domestic commerce, but the exception should not be read as a general prohibition against price-fixing in all parts of the world.","sumSrc":"Oyez","by":{"5":"6"}},{"t":"usc","label":"50 U.S.C. § 4821","url":"https://www.law.cornell.edu/uscode/text/50/4821","subs":["(a)"],"by":{"5":"9"}}]};